// ---- Routines ----

async function ZPROB(base) {
  return base > random(100);
}

async function PICK_ONE(frob) {
  return get(frob, random(get(frob, 0)));
}

async function DEMON(rtn, tick) {
  let cint = 0;
  put(cint = await INT(rtn, true), C_TICK, tick);
  return cint;
}

async function QUEUE(rtn, tick) {
  let cint = 0;
  put(cint = await INT(rtn), C_TICK, tick);
  return cint;
}

async function INT(rtn, demon = false, e = 0, c_ = 0, int = 0) {
  e = g.C_TABLE + C_TABLELEN;
  c_ = g.C_TABLE + g.C_INTS;
  for (;;) {
    if (c_ == e) {
      g.C_INTS = g.C_INTS - C_INTLEN;
      demon && (g.C_DEMONS = g.C_DEMONS - C_INTLEN);
      int = g.C_TABLE + g.C_INTS;
      put(int, C_RTN, rtn);
      return int;
    } else if (eq(get(c_, C_RTN), rtn)) {
      return c_;
    }
    c_ = c_ + C_INTLEN;
  }
}

async function CLOCKER() {
  let c_ = 0, e = 0, tick = 0, flg = false;
  if (g.CLOCK_WAIT) {
    g.CLOCK_WAIT = false;
    return false;
  }
  g.PRESENT_TIME = g.PRESENT_TIME + 1;
  if (g.PRESENT_TIME > 1199) {
    tell("Chief Inspector Klutz walks up to you, seemingly from out of nowhere. \"I'm sorry, Inspector, but your time is up here. I'm sorry that you didn't have any more time to investigate the case. Maybe next time...\" He escorts you to a waiting police car, in which  you go off into the sunset.\n");
    await quit();
  }
  if ((g.MOVES = g.MOVES + 1) > 59) {
    g.MOVES = 0;
    if ((g.SCORE = g.SCORE + 1) > 23) {
      g.SCORE = 0;
    }
  }
  c_ = g.C_TABLE + (g.P_WON ? g.C_INTS : g.C_DEMONS);
  e = g.C_TABLE + C_TABLELEN;
  for (;;) {
    if (c_ == e) {
      return flg;
    } else if (!(get(c_, C_ENABLED$) == 0)) {
      tick = get(c_, C_TICK);
      if (tick == 0) {
      } else {
        put(c_, C_TICK, tick - 1);
        if (!(tick > 1) && (await apply(get(c_, C_RTN)))) {
          flg = true;
        }
      }
    }
    c_ = c_ + C_INTLEN;
  }
}

async function GO() {
  restart: for (;;) {
    putb(g.P_LEXV, 0, 59);
    g.LIT = true;
    g.SCORE = 8;
    g.WINNER = PLAYER;
    g.HERE = SOUTH_LAWN;
    g.P_IT_LOC = g.HERE;
    g.P_IT_OBJECT = false;
    g.P_HIM_HER = MRS_ROBNER;
    g.P_HIM_HER_LOC = FOYER;
    if (!(hasFlag(g.HERE, TOUCHBIT))) {
      enable(await QUEUE(I_START_INTERRUPTS.id, 1));
      await START_MOVEMENT();
      await V_VERSION();
      crlf();
    }
    move(g.WINNER, g.HERE);
    await V_LOOK();
    await MAIN_LOOP();
    continue restart;
  }
}

