async function MAIN_LOOP() {
  let icnt = 0, ocnt = 0, num = 0, cnt = 0, obj = 0, tbl = 0, v_ = 0, ptbl = 0, obj1 = 0, tmp = 0;
  for (;;) {
    cnt = 0;
    obj = false;
    ptbl = true;
    if (g.P_WON = await PARSER()) {
      icnt = get(g.P_PRSI, g.P_MATCHLEN);
      num = (ocnt = get(g.P_PRSO, g.P_MATCHLEN)) == 0 ? ocnt : (ocnt > 1 ? (tbl = g.P_PRSO, icnt == 0 ? (obj = false) : (obj = get(g.P_PRSI, 1)), ocnt) : (icnt > 1 ? (ptbl = false, tbl = g.P_PRSI, obj = get(g.P_PRSO, 1), icnt) : 1));
      if (!(g.QCONTEXT_ROOM == g.HERE)) {
        g.QCONTEXT = false;
      }
      if (!obj && (icnt == 1)) {
        obj = get(g.P_PRSI, 1);
      }
      if (g.PRSA == V.WALK) {
        v_ = await PERFORM(g.PRSA, g.PRSO);
      } else if (num == 0) {
        if ((getb(g.P_SYNTAX, P_SBITS) & P_SONUMS) == 0) {
          v_ = await PERFORM(g.PRSA);
          g.PRSO = false;
        } else {
          tell("There isn't anything to ");
          tmp = get(g.P_ITBL, P_VERBN);
          if (g.P_OFLAG) {
            printB(get(tmp, 0));
          } else {
            await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
          }
          tell("!\n");
          v_ = false;
        }
      } else if (ptbl && (num == 2) && (g.PRSA == V.ARREST)) {
        v_ = await PERFORM(g.PRSA, OBJECT_PAIR);
      } else {
        loop2: for (;;) {
          if ((cnt = cnt + 1) > num) {
            break loop2;
          } else {
            if (ptbl) {
              obj1 = get(g.P_PRSO, cnt);
            } else {
              obj1 = get(g.P_PRSI, cnt);
            }
            if (num > 1) {
              if (obj1 == PLAYER) {
                continue loop2;
              } else if (hasFlag(obj1, DUPLICATE)) {
                continue loop2;
              }
              printD(obj1);
              tell(": ");
            }
            v_ = await QCONTEXT_CHECK(ptbl ? obj1 : obj);
            v_ = await PERFORM(g.PRSA, ptbl ? obj1 : obj, ptbl ? obj : obj1);
            if (v_ == M_FATAL) {
              break loop2;
            }
          }
        }
      }
      if (v_ == M_FATAL) {
        g.P_CONT = false;
      }
    } else {
      g.P_CONT = false;
    }
    if (g.P_WON) {
      if (isVerb(V.TELL, V.BRIEF, V.SUPER_BRIEF, V.VERBOSE, V.TIME, V.SAVE, V.SPACE, V.UNSPACE, V.VERSION, V.QUIT, V.RESTART, V.SCORE, V.SCRIPT, V.UNSCRIPT, V.RESTORE)) {
      } else {
        v_ = await CLOCKER();
      }
    }
  }
}

async function QCONTEXT_CHECK(prso) {
  if (g.QCONTEXT && (loc(g.QCONTEXT) == g.HERE) && (g.QCONTEXT_ROOM == g.HERE) && (g.WINNER == PLAYER)) {
    if (isVerb(V.WHAT) || isVerb(V.FIND) || (isVerb(V.TELL_ME) && (prso == PLAYER)) || (isVerb(V.SHOW) && (prso == PLAYER))) {
      g.WINNER = g.QCONTEXT;
      tell("(said to ", D(g.QCONTEXT), ")\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function PERFORM(a_, o = false, i = false) {
  let v_ = 0, oa = 0, oo = 0, oi = 0;
  oa = g.PRSA;
  oo = g.PRSO;
  oi = g.PRSI;
  g.PRSA = a_;
  if ((IT == i || IT == o) && !(g.P_IT_LOC == g.HERE)) {
    tell("I don't see what you are referring to.\n");
    return M_FATAL;
  } else if ((HIM_HER == i || HIM_HER == o) && !(g.P_HIM_HER_LOC == g.HERE)) {
    v_ = get(g.GLOBAL_CHARACTER_TABLE, getProp(g.P_HIM_HER, P.CHARACTER));
    if (HIM_HER == o) {
      o = v_;
    } else if (HIM_HER == i) {
      i = v_;
    }
  }
  if (o == IT) {
    o = g.P_IT_OBJECT;
  } else if (o == HIM_HER) {
    o = g.P_HIM_HER;
  }
  if (i == IT) {
    i = g.P_IT_OBJECT;
  } else if (i == HIM_HER) {
    i = g.P_HIM_HER;
  }
  g.PRSO = o;
  if (g.PRSO && !(isVerb(V.WALK))) {
    if (hasFlag(g.PRSO, PERSON)) {
      g.P_HIM_HER = g.PRSO;
      g.P_HIM_HER_LOC = g.HERE;
    } else {
      g.P_IT_OBJECT = g.PRSO;
      g.P_IT_LOC = g.HERE;
    }
  }
  g.PRSI = i;
  if (!(a_ == V.AGAIN)) {
    g.L_PRSA = a_;
    if (a_ == V.WALK) {
      g.L_PRSO = false;
    } else {
      g.L_PRSO = o;
    }
    g.L_PRSI = i;
  }
  if (v_ = await apply(getProp(g.WINNER, P.ACTION))) {
  } else if (v_ = await apply(getProp(loc(g.WINNER), P.ACTION), M_BEG)) {
  } else if (v_ = await apply(get(g.PREACTIONS, a_))) {
  } else if (i && (v_ = await apply(getProp(i, P.ACTION)))) {
  } else if (o && !(a_ == V.WALK) && (v_ = await apply(getProp(o, P.ACTION)))) {
  } else if (v_ = await apply(get(g.ACTIONS, a_))) {
  }
  if (!(v_ == M_FATAL)) {
    v_ = await apply(getProp(loc(g.WINNER), P.ACTION), M_END);
  }
  g.PRSA = oa;
  g.PRSO = oo;
  g.PRSI = oi;
  return v_;
}

async function PARSER() {
  let ptr = P_LEXSTART, word = 0, val = 0, verb = false, len = 0, dir = false, nw = 0, lw = 0, num = 0, scnt = 0, cnt = (-1);
  let $1;
  loop1: for (;;) {
    if ((cnt = cnt + 1) > P_ITBLLEN) {
      break loop1;
    } else {
      put(g.P_ITBL, cnt, 0);
    }
  }
  g.P_ADVERB = false;
  g.P_MERGED = false;
  put(g.P_PRSO, g.P_MATCHLEN, 0);
  put(g.P_PRSI, g.P_MATCHLEN, 0);
  put(g.P_BUTS, g.P_MATCHLEN, 0);
  if (!g.QUOTE_FLAG && (g.WINNER != PLAYER)) {
    g.WINNER = PLAYER;
    if (!(hasFlag(loc(g.WINNER), VEHBIT))) {
      g.HERE = loc(g.WINNER);
    }
  }
  if (g.P_CONT) {
    ptr = g.P_CONT;
    g.P_CONT = false;
    if (!(isVerb(V.TELL))) {
      crlf();
    }
  } else {
    g.WINNER = PLAYER;
    g.QUOTE_FLAG = false;
    if (!(hasFlag(loc(g.WINNER), VEHBIT))) {
      g.HERE = loc(g.WINNER);
    }
    scnt = g.P_SPACE;
    loop2: for (;;) {
      if ((scnt = scnt - 1) < 0) {
        break loop2;
      } else {
        crlf();
      }
    }
    tell(">");
    await read(g.P_INBUF, g.P_LEXV);
  }
  g.P_LEN = getb(g.P_LEXV, P_LEXWORDS);
  if (g.P_LEN == 0) {
    tell("What?\n");
    return false;
  } else if (eq(word = get(g.P_LEXV, ptr), W.WHY, W.HOW, W.WHEN) || (word == W.IS || word == W.DID || word == W.ARE)) {
    tell("Detectives are expected to know how to conduct an interrogation; please re-read your casebook for remedial instruction. Remember that the documentary evidence enclosed contains the answers to all of the important questions which cannot be asked directly.\n");
    return false;
  }
  len = g.P_LEN;
  g.P_DIR = false;
  g.P_NCN = 0;
  g.P_GETFLAGS = 0;
  loop3: for (;;) {
    if ((g.P_LEN = g.P_LEN - 1) < 0) {
      g.QUOTE_FLAG = false;
      break loop3;
    } else if ((word = get(g.P_LEXV, ptr)) || (word = await NUMBER$(ptr))) {
      if ((word == W.TO) && (verb == ACT.TELL || verb == ACT.ASK)) {
        word = W.QUOTE;
      } else if ((word == W.THEN) && !verb) {
        put(g.P_ITBL, P_VERB, ACT.TELL);
        put(g.P_ITBL, P_VERBN, 0);
        word = W.QUOTE;
      }
      if ((word == W._) && (lw == W.MRS || lw == W.MR || lw == W.MS)) {
        lw = 0;
      } else if ((word == W.THEN || word == W._) || (word == W.QUOTE)) {
        if (word == W.QUOTE) {
          if (g.QUOTE_FLAG) {
            g.QUOTE_FLAG = false;
          } else {
            g.QUOTE_FLAG = true;
          }
        }
        (g.P_LEN == 0) || (g.P_CONT = ptr + P_LEXELEN);
        putb(g.P_LEXV, P_LEXWORDS, g.P_LEN);
        break loop3;
      } else if ((val = await WT$(word, PS$DIRECTION, P1$DIRECTION)) && ((len == 1) || ((len == 2) && (verb == ACT.WALK)) || (eq(nw = get(g.P_LEXV, ptr + P_LEXELEN), W.THEN, W.QUOTE) && (len > 2)) || ((nw == W._) && (len > 1)) || (g.QUOTE_FLAG && (len == 2) && (nw == W.QUOTE)) || ((len > 2) && (nw == W.COMMA || nw == W.AND)))) {
        dir = val;
        if (nw == W.COMMA || nw == W.AND) {
          put(g.P_LEXV, ptr + P_LEXELEN, W.THEN);
        }
        if (!(len > 2)) {
          g.QUOTE_FLAG = false;
          break loop3;
        }
      } else if ((val = await WT$(word, PS$VERB, P1$VERB)) && (!verb || (verb == ACT.WHAT))) {
        verb = val;
        put(g.P_ITBL, P_VERB, val);
        put(g.P_ITBL, P_VERBN, g.P_VTBL);
        put(g.P_VTBL, 0, word);
        putb(g.P_VTBL, 2, getb(g.P_LEXV, num = (ptr * 2) + 2));
        putb(g.P_VTBL, 3, getb(g.P_LEXV, num + 1));
      } else if ((val = await WT$(word, PS$PREPOSITION, 0)) || (((word == W.ALL || word == W.ONE || word == W.A) || (await WT$(word, PS$ADJECTIVE)) || (await WT$(word, PS$OBJECT))) && (val = 0, true))) {
        if ((g.P_LEN > 0) && eq(get(g.P_LEXV, ptr + P_LEXELEN), W.OF) && !(verb == ACT.ACCUSE) && (val == 0) && !(word == W.ALL || word == W.ONE || word == W.A)) {
        } else if (!(val == 0) && ((g.P_LEN == 0) || eq(get(g.P_LEXV, ptr + 2), W.THEN, W._))) {
          if (g.P_NCN < 2) {
            put(g.P_ITBL, P_PREP1, val);
            put(g.P_ITBL, P_PREP1N, word);
          }
        } else if (g.P_NCN == 2) {
          tell("There were more than two nouns in that sentence.\n");
          return false;
        } else {
          g.P_NCN = g.P_NCN + 1;
          $1 = ptr = await CLAUSE(ptr, val, word);
          if (!$1) {
            return false;
          }
          if (ptr < 0) {
            g.QUOTE_FLAG = false;
            break loop3;
          }
        }
      } else if ((word == W.CAREFULLY || word == W.QUIETLY) || (word == W.SLOWLY || word == W.QUICKLY || word == W.BRIEFLY)) {
        g.P_ADVERB = word;
      } else if (await WT$(word, PS$BUZZ_WORD)) {
      } else {
        await CANT_USE(ptr);
        return false;
      }
    } else {
      await UNKNOWN_WORD(ptr);
      return false;
    }
    lw = word;
    ptr = ptr + P_LEXELEN;
  }
  if (dir) {
    g.PRSA = V.WALK;
    g.PRSO = dir;
    return true;
  }
  if (g.P_OFLAG) {
    await ORPHAN_MERGE();
  }
  if (eq(get(g.P_ITBL, P_VERB), 0)) {
    put(g.P_ITBL, P_VERB, ACT.CALL);
  }
  if ((await SYNTAX_CHECK()) && (await SNARF_OBJECTS()) && (await TAKE_CHECK()) && (await MANY_CHECK())) {
    return true;
  } else {
    return false;
  }
}

async function WT$(ptr, bit, b1 = 5) {
  let offset = P_P1OFF, typ = 0;
  if (btst(typ = getb(ptr, P_PSOFF), bit)) {
    if (b1 > 4) {
      return true;
    } else {
      typ = typ & P_P1BITS;
      if (!(typ == b1)) {
        offset = offset + 1;
      }
      return getb(ptr, offset);
    }
  } else {
    return false;
  }
}

async function CLAUSE(ptr, val, word) {
  let off = 0, num = 0, andflg = false, first$$ = true, nw = 0, lw = 0;
  off = (g.P_NCN - 1) * 2;
  if (!(val == 0)) {
    put(g.P_ITBL, num = P_PREP1 + off, val);
    put(g.P_ITBL, num + 1, word);
    ptr = ptr + P_LEXELEN;
  } else {
    g.P_LEN = g.P_LEN + 1;
  }
  if (g.P_LEN == 0) {
    g.P_NCN = g.P_NCN - 1;
    return -1;
  }
  put(g.P_ITBL, num = P_NC1 + off, g.P_LEXV + (ptr * 2));
  if (eq(get(g.P_LEXV, ptr), W.THE, W.A, W.AN)) {
    put(g.P_ITBL, num, get(g.P_ITBL, num) + 4);
  }
  for (;;) {
    if ((g.P_LEN = g.P_LEN - 1) < 0) {
      put(g.P_ITBL, num + 1, g.P_LEXV + (ptr * 2));
      return -1;
    }
    if ((word = get(g.P_LEXV, ptr)) || (word = await NUMBER$(ptr))) {
      if (g.P_LEN == 0) {
        nw = 0;
      } else {
        nw = get(g.P_LEXV, ptr + P_LEXELEN);
      }
      if ((word == W.OF) && eq(get(g.P_ITBL, P_VERB), ACT.ACCUSE)) {
        put(g.P_LEXV, ptr, W.WITH);
        word = W.WITH;
      }
      if ((word == W._) && (lw == W.MRS || lw == W.MR || lw == W.MS)) {
        lw = 0;
      } else if (word == W.AND || word == W.COMMA) {
        andflg = true;
      } else if (word == W.ALL || word == W.ONE) {
        if (nw == W.OF) {
          g.P_LEN = g.P_LEN - 1;
          ptr = ptr + P_LEXELEN;
        }
      } else if ((word == W.THEN || word == W._) || ((await WT$(word, PS$PREPOSITION)) && !first$$)) {
        g.P_LEN = g.P_LEN + 1;
        put(g.P_ITBL, num + 1, g.P_LEXV + (ptr * 2));
        return ptr - P_LEXELEN;
      } else if (await WT$(word, PS$OBJECT)) {
        if ((await WT$(word, PS$ADJECTIVE, P1$ADJECTIVE)) && !(nw == 0) && (await WT$(nw, PS$OBJECT))) {
        } else if (!andflg && !(nw == W.BUT || nw == W.EXCEPT) && !(nw == W.AND || nw == W.COMMA)) {
          put(g.P_ITBL, num + 1, g.P_LEXV + ((ptr + 2) * 2));
          return ptr;
        } else {
          andflg = false;
        }
      } else if ((await WT$(word, PS$ADJECTIVE)) || (await WT$(word, PS$BUZZ_WORD))) {
      } else if (andflg && ((await WT$(word, PS$DIRECTION)) || (await WT$(word, PS$VERB)))) {
        ptr = ptr - 4;
        put(g.P_LEXV, ptr + 2, W.THEN);
        g.P_LEN = g.P_LEN + 2;
      } else if (await WT$(word, PS$PREPOSITION)) {
      } else {
        await CANT_USE(ptr);
        return false;
      }
    } else {
      await UNKNOWN_WORD(ptr);
      return false;
    }
    lw = word;
    first$$ = false;
    ptr = ptr + P_LEXELEN;
  }
}

async function NUMBER$(ptr) {
  let cnt = 0, bptr = 0, chr = 0, sum = 0, tim = false;
  cnt = getb(g.P_LEXV + (ptr * 2), 2);
  bptr = getb(g.P_LEXV + (ptr * 2), 3);
  loop1: for (;;) {
    if ((cnt = cnt - 1) < 0) {
      break loop1;
    } else {
      chr = getb(g.P_INBUF, bptr);
      if (chr == 58) {
        tim = sum;
        sum = 0;
      } else if (sum > 10000) {
        return false;
      } else if ((chr < 58) && (chr > 47)) {
        sum = (sum * 10) + (chr - 48);
      } else {
        return false;
      }
      bptr = bptr + 1;
    }
  }
  put(g.P_LEXV, ptr, W.INTNUM);
  if (sum > 1000) {
    return false;
  } else if (tim) {
    if (tim < 8) {
      tim = tim + 12;
    } else if (tim > 23) {
      return false;
    }
    sum = sum + (tim * 60);
  }
  g.P_NUMBER = sum;
  return W.INTNUM;
}

async function ORPHAN_MERGE() {
  let cnt = (-1), temp = 0, verb = 0, beg = 0, end = 0, adj = false, wrd = 0;
  g.P_OFLAG = false;
  if (!((verb = get(g.P_ITBL, P_VERB)) == 0) && !(verb == get(g.P_OTBL, P_VERB))) {
    return false;
  } else if (g.P_NCN == 2) {
    return false;
  } else if (eq(get(g.P_OTBL, P_NC1), 1)) {
    if (eq(temp = get(g.P_ITBL, P_PREP1), get(g.P_OTBL, P_PREP1)) || (temp == 0)) {
      put(g.P_OTBL, P_NC1, get(g.P_ITBL, P_NC1));
      put(g.P_OTBL, P_NC1L, get(g.P_ITBL, P_NC1L));
    } else {
      return false;
    }
  } else if (eq(get(g.P_OTBL, P_NC2), 1)) {
    if (eq(temp = get(g.P_ITBL, P_PREP1), get(g.P_OTBL, P_PREP2)) || (temp == 0)) {
      put(g.P_OTBL, P_NC2, get(g.P_ITBL, P_NC1));
      put(g.P_OTBL, P_NC2L, get(g.P_ITBL, P_NC1L));
      g.P_NCN = 2;
    } else {
      return false;
    }
  } else if (g.P_ACLAUSE) {
    if (!(g.P_NCN == 1)) {
      g.P_ACLAUSE = false;
      return false;
    } else {
      beg = get(g.P_ITBL, P_NC1);
      end = get(g.P_ITBL, P_NC1L);
      loop1: for (;;) {
        if (beg == end) {
          if (adj) {
            await ACLAUSE_WIN(adj);
            break loop1;
          } else {
            g.P_ACLAUSE = false;
            return false;
          }
        } else if (!adj && btst(getb(wrd = get(beg, 0), P_PSOFF), PS$ADJECTIVE)) {
          adj = wrd;
        } else if (btst(getb(wrd, P_PSOFF), PS$OBJECT) || (wrd == W.ONE)) {
          if (!(wrd == g.P_ANAM || wrd == W.ONE)) {
            return false;
          } else {
            await ACLAUSE_WIN(adj);
            break loop1;
          }
        }
        beg = beg + P_WORDLEN;
      }
    }
  }
  for (;;) {
    if ((cnt = cnt + 1) > P_ITBLLEN) {
      g.P_MERGED = true;
      return true;
    } else {
      put(g.P_ITBL, cnt, get(g.P_OTBL, cnt));
    }
  }
  return true;
}

async function ACLAUSE_WIN(adj) {
  g.P_CCSRC = g.P_OTBL;
  await CLAUSE_COPY(g.P_ACLAUSE, g.P_ACLAUSE + 1, adj);
  !(eq(get(g.P_OTBL, P_NC2), 0)) && (g.P_NCN = 2, true);
  g.P_ACLAUSE = false;
  return true;
}

async function WORD_PRINT(cnt, buf) {
  for (;;) {
    if (--cnt < 0) {
      return true;
    } else {
      printC(getb(g.P_INBUF, buf));
      buf = buf + 1;
    }
  }
}

async function UNKNOWN_WORD(ptr) {
  let buf = 0;
  tell("The word '");
  await WORD_PRINT(getb(g.P_LEXV + (buf = ptr * 2), 2), getb(g.P_LEXV + buf, 3));
  tell("' isn't in your vocabulary.\n");
  g.QUOTE_FLAG = false;
  return g.P_OFLAG = false;
}

async function CANT_USE(ptr) {
  let buf = 0;
  tell("The word '");
  await WORD_PRINT(getb(g.P_LEXV + (buf = ptr * 2), 2), getb(g.P_LEXV + buf, 3));
  tell("' can't be used in that sense.\n");
  g.QUOTE_FLAG = false;
  return g.P_OFLAG = false;
}

async function SYNTAX_CHECK() {
  let syn = 0, len = 0, num = 0, obj = 0, drive1 = false, drive2 = false, prep = 0, verb = 0, tmp = 0;
  if ((verb = get(g.P_ITBL, P_VERB)) == 0) {
    tell("There's no verb in that sentence!\n");
    return false;
  }
  syn = get(g.VERBS, 255 - verb);
  len = getb(syn, 0);
  syn = syn + 1;
  loop1: for (;;) {
    num = getb(syn, P_SBITS) & P_SONUMS;
    if (!(num < 1) && (g.P_NCN == 0) && (((prep = get(g.P_ITBL, P_PREP1)) == 0) || (prep == getb(syn, P_SPREP1)))) {
      drive1 = syn;
    } else if (eq(getb(syn, P_SPREP1), get(g.P_ITBL, P_PREP1))) {
      if ((num == 2) && (g.P_NCN == 1)) {
        drive2 = syn;
      } else if (eq(getb(syn, P_SPREP2), get(g.P_ITBL, P_PREP2))) {
        await SYNTAX_FOUND(syn);
        return true;
      }
    }
    if (--len < 1) {
      if (drive1 || drive2) {
        break loop1;
      } else {
        tell("That last sentence didn't make sense.\n");
        return false;
      }
    } else {
      syn = syn + P_SYNLEN;
    }
  }
  if (drive1 && (obj = await GWIM(getb(drive1, P_SFWIM1), getb(drive1, P_SLOC1), getb(drive1, P_SPREP1)))) {
    put(g.P_PRSO, g.P_MATCHLEN, 1);
    put(g.P_PRSO, 1, obj);
    return await SYNTAX_FOUND(drive1);
  } else if (drive2 && (obj = await GWIM(getb(drive2, P_SFWIM2), getb(drive2, P_SLOC2), getb(drive2, P_SPREP2)))) {
    put(g.P_PRSI, g.P_MATCHLEN, 1);
    put(g.P_PRSI, 1, obj);
    return await SYNTAX_FOUND(drive2);
  } else if (verb == ACT.FIND || verb == ACT.WHAT) {
    tell("That question cannot be answered.\n");
    return false;
  } else {
    await ORPHAN(drive1, drive2);
    tell("What do you want to ");
    tmp = get(g.P_OTBL, P_VERBN);
    if (tmp == 0) {
      tell("tell");
    } else if (getb(g.P_VTBL, 2) == 0) {
      printB(get(tmp, 0));
    } else {
      await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
      putb(g.P_VTBL, 2, 0);
    }
    if (drive2) {
      await CLAUSE_PRINT(P_NC1, P_NC1L);
    }
    g.P_OFLAG = true;
    await PREP_PRINT(drive1 ? getb(drive1, P_SPREP1) : getb(drive2, P_SPREP2));
    tell("?\n");
    return false;
  }
}

async function ORPHAN(d1, d2) {
  let cnt = (-1);
  put(g.P_OCLAUSE, g.P_MATCHLEN, 0);
  g.P_CCSRC = g.P_ITBL;
  loop1: for (;;) {
    if (++cnt > P_ITBLLEN) {
      break loop1;
    } else {
      put(g.P_OTBL, cnt, get(g.P_ITBL, cnt));
    }
  }
  if (g.P_NCN == 2) {
    await CLAUSE_COPY(P_NC2, P_NC2L);
  }
  if (!(g.P_NCN < 1)) {
    await CLAUSE_COPY(P_NC1, P_NC1L);
  }
  if (d1) {
    put(g.P_OTBL, P_PREP1, getb(d1, P_SPREP1));
    return put(g.P_OTBL, P_NC1, 1);
  } else if (d2) {
    put(g.P_OTBL, P_PREP2, getb(d2, P_SPREP2));
    return put(g.P_OTBL, P_NC2, 1);
  } else {
    return false;
  }
}

async function CLAUSE_PRINT(bptr, eptr, the$ = true) {
  return await BUFFER_PRINT(get(g.P_ITBL, bptr), get(g.P_ITBL, eptr), the$);
}

async function BUFFER_PRINT(beg, end, cp) {
  let nosp = false, wrd = 0, first$$ = true, pn = false;
  for (;;) {
    if (beg == end) {
      return true;
    } else {
      if (nosp) {
        nosp = false;
      } else {
        tell(" ");
      }
      if (eq(wrd = get(beg, 0), W._)) {
        nosp = true;
      } else if (wrd == W.MRS) {
        tell("Mrs.");
        pn = true;
      } else if (wrd == W.MS) {
        tell("Ms.");
        pn = true;
      } else if (wrd == W.MR) {
        tell("Mr.");
        pn = true;
      } else if ((wrd == W.BAXTER || wrd == W.GEORGE || wrd == W.ROBNER) || (wrd == W.MCNABB || wrd == W.ROURKE || wrd == W.DUNBAR) || (wrd == W.STEVEN || wrd == W.STEVE || wrd == W.DUFFY)) {
        await CAPITALIZE(beg);
        pn = true;
      } else {
        if (first$$ && !pn && cp) {
          tell("the ");
        }
        if (g.P_OFLAG) {
          printB(wrd);
        } else if ((wrd == W.IT) && (g.P_IT_LOC == g.HERE)) {
          printD(g.P_IT_OBJECT);
        } else {
          await WORD_PRINT(getb(beg, 2), getb(beg, 3));
        }
        first$$ = false;
      }
    }
    beg = beg + P_WORDLEN;
  }
}

async function CAPITALIZE(ptr) {
  printC(getb(g.P_INBUF, getb(ptr, 3)) - 32);
  return await WORD_PRINT(getb(ptr, 2) - 1, getb(ptr, 3) + 1);
}

async function PREP_PRINT(prep) {
  let wrd = 0;
  if (!(prep == 0)) {
    tell(" ");
    wrd = await PREP_FIND(prep);
    if (wrd == W.AGAINST) {
      tell("against");
      return true;
    } else {
      return printB(wrd);
    }
  } else {
    return false;
  }
}

async function CLAUSE_COPY(bptr, eptr, insert = false) {
  let beg = 0, end = 0;
  beg = get(g.P_CCSRC, bptr);
  end = get(g.P_CCSRC, eptr);
  put(g.P_OTBL, bptr, g.P_OCLAUSE + ((get(g.P_OCLAUSE, g.P_MATCHLEN) * P_LEXELEN) + 2));
  for (;;) {
    if (beg == end) {
      put(g.P_OTBL, eptr, g.P_OCLAUSE + ((get(g.P_OCLAUSE, g.P_MATCHLEN) * P_LEXELEN) + 2));
      return true;
    } else {
      if (insert && (g.P_ANAM == get(beg, 0))) {
        await CLAUSE_ADD(insert);
      }
      await CLAUSE_ADD(get(beg, 0));
    }
    beg = beg + P_WORDLEN;
  }
}

async function CLAUSE_ADD(wrd) {
  let ptr = 0;
  ptr = get(g.P_OCLAUSE, g.P_MATCHLEN) + 2;
  put(g.P_OCLAUSE, ptr - 1, wrd);
  put(g.P_OCLAUSE, ptr, 0);
  return put(g.P_OCLAUSE, g.P_MATCHLEN, ptr);
}

async function PREP_FIND(prep) {
  let cnt = 0, size = 0;
  size = get(g.PREPOSITIONS, 0) * 2;
  for (;;) {
    if (++cnt > size) {
      return false;
    } else if (eq(get(g.PREPOSITIONS, cnt), prep)) {
      return get(g.PREPOSITIONS, cnt - 1);
    }
  }
}

async function SYNTAX_FOUND(syn) {
  g.P_SYNTAX = syn;
  return g.PRSA = getb(syn, P_SACTION);
}

async function GWIM(gbit, lbit, prep) {
  let obj = 0;
  if (gbit == RMUNGBIT) {
    return ROOMS;
  }
  g.P_GWIMBIT = gbit;
  g.P_SLOCBITS = lbit;
  put(g.P_MERGE, g.P_MATCHLEN, 0);
  if (await GET_OBJECT(g.P_MERGE, false)) {
    g.P_GWIMBIT = 0;
    if (eq(get(g.P_MERGE, g.P_MATCHLEN), 1)) {
      obj = get(g.P_MERGE, 1);
      tell("(");
      if (!(prep == 0)) {
        printB(await PREP_FIND(prep));
        if (!(hasFlag(obj, PERSON))) {
          tell(" the ");
        } else {
          tell(" ");
        }
      }
      tell(D(obj), ")\n");
      return obj;
    } else {
      return false;
    }
  } else {
    g.P_GWIMBIT = 0;
    return false;
  }
}

async function SNARF_OBJECTS() {
  let ptr = 0;
  let $1, $2;
  if (!(eq(ptr = get(g.P_ITBL, P_NC1), 0))) {
    g.P_SLOCBITS = getb(g.P_SYNTAX, P_SLOC1);
    $1 = await SNARFEM(ptr, get(g.P_ITBL, P_NC1L), g.P_PRSO);
    if (!$1) {
      return false;
    }
    (get(g.P_BUTS, g.P_MATCHLEN) == 0) || (g.P_PRSO = await BUT_MERGE(g.P_PRSO));
  }
  if (!(eq(ptr = get(g.P_ITBL, P_NC2), 0))) {
    g.P_SLOCBITS = getb(g.P_SYNTAX, P_SLOC2);
    $2 = await SNARFEM(ptr, get(g.P_ITBL, P_NC2L), g.P_PRSI);
    if (!$2) {
      return false;
    }
    if (!(get(g.P_BUTS, g.P_MATCHLEN) == 0)) {
      if (eq(get(g.P_PRSI, g.P_MATCHLEN), 1)) {
        g.P_PRSO = await BUT_MERGE(g.P_PRSO);
      } else {
        g.P_PRSI = await BUT_MERGE(g.P_PRSI);
      }
    }
  }
  return true;
}

async function BUT_MERGE(tbl) {
  let len = 0, butlen = 0, cnt = 1, matches = 0, obj = 0, ntbl = 0;
  len = get(tbl, g.P_MATCHLEN);
  put(g.P_MERGE, g.P_MATCHLEN, 0);
  loop1: for (;;) {
    if (--len < 0) {
      break loop1;
    } else if (await ZMEMQ(obj = get(tbl, cnt), g.P_BUTS)) {
    } else {
      put(g.P_MERGE, matches + 1, obj);
      matches = matches + 1;
    }
    cnt = cnt + 1;
  }
  put(g.P_MERGE, g.P_MATCHLEN, matches);
  ntbl = g.P_MERGE;
  g.P_MERGE = tbl;
  return ntbl;
}

async function SNARFEM(ptr, eptr, tbl) {
  let and = false, but = false, len = 0, wv = 0, word = 0, nw = 0;
  let $1, $2, $3, $4;
  g.P_GETFLAGS = 0;
  g.P_CSPTR = ptr;
  g.P_CEPTR = eptr;
  put(g.P_BUTS, g.P_MATCHLEN, 0);
  put(tbl, g.P_MATCHLEN, 0);
  word = get(ptr, 0);
  for (;;) {
    if (ptr == eptr) {
      return await GET_OBJECT(but || tbl);
    } else {
      nw = get(ptr, P_LEXELEN);
      if (word == W.ALL) {
        g.P_GETFLAGS = P_ALL;
        if (nw == W.OF) {
          ptr = ptr + P_WORDLEN;
        }
      } else if (word == W.BUT || word == W.EXCEPT) {
        $1 = await GET_OBJECT(but || tbl);
        if (!$1) {
          return false;
        }
        but = g.P_BUTS;
        put(but, g.P_MATCHLEN, 0);
      } else if (word == W.A || word == W.ONE) {
        if (!g.P_ADJ) {
          g.P_GETFLAGS = P_ONE;
          if (nw == W.OF) {
            ptr = ptr + P_WORDLEN;
          }
        } else {
          g.P_NAM = g.P_ONEOBJ;
          $2 = await GET_OBJECT(but || tbl);
          if (!$2) {
            return false;
          }
          $3 = nw == 0;
          if ($3) {
            return true;
          }
        }
      } else if ((word == W.AND || word == W.COMMA) && !(nw == W.AND || nw == W.COMMA)) {
        $4 = await GET_OBJECT(but || tbl);
        if (!$4) {
          return false;
        }
      } else if (await WT$(word, PS$BUZZ_WORD)) {
      } else if (word == W.AND || word == W.COMMA) {
      } else if (word == W.OF) {
        if (g.P_GETFLAGS == 0) {
          g.P_GETFLAGS = P_INHIBIT;
        }
      } else if ((wv = await WT$(word, PS$ADJECTIVE, P1$ADJECTIVE)) && !g.P_ADJ) {
        g.P_ADJ = wv;
        g.P_ADJN = word;
      } else if (await WT$(word, PS$OBJECT, P1$OBJECT)) {
        g.P_NAM = word;
        g.P_ONEOBJ = word;
      }
    }
    if (!(ptr == eptr)) {
      ptr = ptr + P_WORDLEN;
      word = nw;
    }
  }
}

async function GET_OBJECT(tbl, vrb = true) {
  let bits = 0, len = 0, xbits = 0, tlen = 0, gcheck = false, olen = 0;
  xbits = g.P_SLOCBITS;
  tlen = get(tbl, g.P_MATCHLEN);
  if (btst(g.P_GETFLAGS, P_INHIBIT)) {
    return true;
  }
  if (!g.P_NAM && g.P_ADJ && (await WT$(g.P_ADJN, PS$OBJECT, P1$OBJECT))) {
    g.P_NAM = g.P_ADJN;
    g.P_ADJ = false;
  }
  if (!g.P_NAM && !g.P_ADJ && !(g.P_GETFLAGS == P_ALL) && (g.P_GWIMBIT == 0)) {
    if (vrb) {
      tell("Your last sentence seemed to be missing a noun.\n");
    }
    return false;
  }
  if (!(g.P_GETFLAGS == P_ALL) || (g.P_SLOCBITS == 0)) {
    g.P_SLOCBITS = -1;
  }
  g.P_TABLE = tbl;
  loop1: for (;;) {
    if (gcheck) {
      await GLOBAL_CHECK(tbl);
    } else {
      if (g.LIT) {
        await DO_SL(g.HERE, SOG, SIR);
      }
      await DO_SL(PLAYER, SH, SC);
    }
    len = get(tbl, g.P_MATCHLEN) - tlen;
    if (btst(g.P_GETFLAGS, P_ALL)) {
    } else if (btst(g.P_GETFLAGS, P_ONE) && !(len == 0)) {
      if (!(len == 1)) {
        put(tbl, 1, get(tbl, random(len)));
        tell("(How about the ");
        printD(get(tbl, 1));
        tell("?)\n");
      }
      put(tbl, g.P_MATCHLEN, 1);
    } else if ((len > 1) || ((len == 0) && !(g.P_SLOCBITS == (-1)))) {
      if (g.P_SLOCBITS == (-1)) {
        g.P_SLOCBITS = xbits;
        olen = len;
        put(tbl, g.P_MATCHLEN, get(tbl, g.P_MATCHLEN) - len);
        continue loop1;
      } else {
        if (len == 0) {
          len = olen;
        }
        if (vrb && g.P_NAM) {
          await WHICH_PRINT(tlen, len, tbl);
          g.P_ACLAUSE = tbl == g.P_PRSO ? P_NC1 : P_NC2;
          g.P_AADJ = g.P_ADJ;
          g.P_ANAM = g.P_NAM;
          await ORPHAN(false, false);
          g.P_OFLAG = true;
        } else if (vrb) {
          tell("You must supply a verb!\n");
        }
        g.P_NAM = false;
        g.P_ADJ = false;
        return false;
      }
    } else if ((len == 0) && gcheck) {
      if (vrb) {
        if (g.LIT) {
          tell("You can't see any");
          if (g.P_OFLAG) {
            if (g.P_ADJ) {
              tell(" ");
              printB(g.P_ADJN);
            }
            if (g.P_NAM) {
              tell(" ");
              printB(g.P_NAM);
            }
          } else {
            await BUFFER_PRINT(g.P_CSPTR, g.P_CEPTR, false);
          }
          tell(" here.\n");
        } else {
          tell("It's too dark to see.\n");
        }
      }
      g.P_NAM = false;
      g.P_ADJ = false;
      return false;
    } else if (len == 0) {
      gcheck = true;
      continue loop1;
    }
    g.P_ADJ = false;
    g.P_NAM = false;
    g.P_SLOCBITS = xbits;
    return true;
  }
}

async function WHICH_PRINT(tlen, len, tbl) {
  let obj = 0, rlen = 0;
  rlen = len;
  tell("Which");
  if (g.P_OFLAG || g.P_MERGED) {
    tell(" ");
    printB(g.P_NAM);
  } else if (tbl == g.P_PRSO) {
    await CLAUSE_PRINT(P_NC1, P_NC1L, false);
  } else {
    await CLAUSE_PRINT(P_NC2, P_NC2L, false);
  }
  tell(" do you mean, ");
  for (;;) {
    tlen = tlen + 1;
    obj = get(tbl, tlen);
    if (!(hasFlag(obj, PERSON))) {
      tell("the ");
    }
    tell(D(obj));
    if (len == 2) {
      if (!(rlen == 2)) {
        tell(",");
      }
      tell(" or ");
    } else if (len > 2) {
      tell(", ");
    }
    if ((len = len - 1) < 1) {
      tell("?\n");
      return true;
    }
  }
}

async function GLOBAL_CHECK(tbl) {
  let len = 0, rmg = 0, rmgl = 0, cnt = 0, obj = 0, obits = 0, foo = 0;
  len = get(tbl, g.P_MATCHLEN);
  obits = g.P_SLOCBITS;
  if (rmg = getPropAddr(g.HERE, P.GLOBAL)) {
    rmgl = propSize(rmg) - 1;
    loop1: for (;;) {
      if (await THIS_IT$(obj = getb(rmg, cnt), tbl)) {
        await OBJ_FOUND(obj, tbl);
      }
      if (++cnt > rmgl) {
        break loop1;
      }
    }
  }
  if (rmg = getPropAddr(g.HERE, P.PSEUDO)) {
    rmgl = div(propSize(rmg), 4) - 1;
    cnt = 0;
    loop2: for (;;) {
      if (g.P_NAM == get(rmg, cnt * 2)) {
        putProp(PSEUDO_OBJECT, P.ACTION, get(rmg, (cnt * 2) + 1));
        foo = getPropAddr(PSEUDO_OBJECT, P.ACTION) - 5;
        put(foo, 0, get(g.P_NAM, 0));
        put(foo, 1, get(g.P_NAM, 1));
        await OBJ_FOUND(PSEUDO_OBJECT, tbl);
        break loop2;
      } else if (++cnt > rmgl) {
        break loop2;
      }
    }
  }
  if (eq(get(tbl, g.P_MATCHLEN), len)) {
    g.P_SLOCBITS = -1;
    g.P_TABLE = tbl;
    await DO_SL(GLOBAL_OBJECTS, 1, 1);
    g.P_SLOCBITS = obits;
    if (get(tbl, g.P_MATCHLEN) == 0) {
      if ((g.PRSA == V.LOOK_INSIDE || g.PRSA == V.SEARCH) || (g.PRSA == V.EXAMINE || g.PRSA == V.FIND || g.PRSA == V.THROUGH)) {
        return await DO_SL(ROOMS, 1, 1);
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function DO_SL(obj, bit1, bit2) {
  let bits = 0;
  if (btst(g.P_SLOCBITS, bit1 + bit2)) {
    return await SEARCH_LIST(obj, g.P_TABLE, P_SRCALL);
  } else {
    if (btst(g.P_SLOCBITS, bit1)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCTOP);
    } else if (btst(g.P_SLOCBITS, bit2)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCBOT);
    } else {
      return true;
    }
  }
}

async function SEARCH_LIST(obj, tbl, lvl) {
  let fls = 0, nobj = 0;
  if (obj = first(obj)) {
    for (;;) {
      if (!(lvl == P_SRCBOT) && getPropAddr(obj, P.SYNONYM) && (await THIS_IT$(obj, tbl))) {
        await OBJ_FOUND(obj, tbl);
      }
      if ((!(lvl == P_SRCTOP) || hasFlag(obj, SEARCHBIT) || hasFlag(obj, SURFACEBIT)) && (nobj = first(obj)) && (hasFlag(obj, OPENBIT) || hasFlag(obj, TRANSBIT))) {
        fls = await SEARCH_LIST(obj, tbl, hasFlag(obj, SURFACEBIT) ? P_SRCALL : (hasFlag(obj, SEARCHBIT) ? P_SRCALL : P_SRCTOP));
      }
      if (obj = next(obj)) {
      } else {
        return true;
      }
    }
  } else {
    return false;
  }
}

async function OBJ_FOUND(obj, tbl) {
  let ptr = 0;
  ptr = get(tbl, g.P_MATCHLEN);
  put(tbl, ptr + 1, obj);
  return put(tbl, g.P_MATCHLEN, ptr + 1);
}

async function TAKE_CHECK() {
  return (await ITAKE_CHECK(g.P_PRSO, getb(g.P_SYNTAX, P_SLOC1))) && (await ITAKE_CHECK(g.P_PRSI, getb(g.P_SYNTAX, P_SLOC2)));
}

async function ITAKE_CHECK(tbl, bits) {
  let ptr = 0, obj = 0, taken = 0;
  if ((ptr = get(tbl, g.P_MATCHLEN)) && btst(bits, STAKE)) {
    for (;;) {
      if ((ptr = ptr - 1) < 0) {
        return true;
      } else {
        obj = get(tbl, ptr + 1);
        if (obj == IT) {
          obj = g.P_IT_OBJECT;
        }
        if (!(loc(obj) == g.WINNER)) {
          g.PRSO = obj;
          if (hasFlag(obj, TRYTAKEBIT)) {
            taken = true;
          } else if (eq(await ITAKE(false), true)) {
            taken = false;
          } else {
            taken = true;
          }
          if (taken && btst(bits, SHAVE)) {
            tell("You don't have the ");
            printD(obj);
            tell(".\n");
            return false;
          } else if (!taken) {
            tell("(Taken)\n");
          }
        }
      }
    }
  } else {
    return true;
  }
}

async function MANY_CHECK() {
  let loss = false, tmp = 0;
  if ((get(g.P_PRSO, g.P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC1), SMANY))) {
    loss = 1;
  } else if ((get(g.P_PRSI, g.P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC2), SMANY))) {
    loss = 2;
  }
  if (loss) {
    tell("You can't use multiple ");
    if (loss == 2) {
      tell("in");
    }
    tell("direct objects with '");
    tmp = get(g.P_ITBL, P_VERBN);
    if (tmp == 0) {
      tell("tell");
    } else if (g.P_OFLAG) {
      printB(get(tmp, 0));
    } else {
      await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    }
    tell("'.\n");
    return false;
  } else {
    return true;
  }
}

async function ZMEMQ(itm, tbl, size = (-1)) {
  let cnt = 1;
  if (!tbl) {
    return false;
  }
  if (!(size < 0)) {
    cnt = 0;
  } else {
    size = get(tbl, 0);
  }
  for (;;) {
    if (itm == get(tbl, cnt)) {
      return true;
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function ZMEMQB(itm, tbl, size) {
  let cnt = 0;
  for (;;) {
    if (itm == getb(tbl, cnt)) {
      return true;
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function LIT$(rm) {
  let ohere = 0, lit = false;
  g.P_GWIMBIT = ONBIT;
  ohere = g.HERE;
  g.HERE = rm;
  if (hasFlag(rm, ONBIT) || g.ALWAYS_LIT) {
    lit = true;
  } else {
    put(g.P_MERGE, g.P_MATCHLEN, 0);
    g.P_TABLE = g.P_MERGE;
    g.P_SLOCBITS = -1;
    if (ohere == rm) {
      await DO_SL(g.WINNER, 1, 1);
    }
    await DO_SL(rm, 1, 1);
    if (get(g.P_TABLE, g.P_MATCHLEN) > 0) {
      lit = true;
    }
  }
  g.HERE = ohere;
  g.P_GWIMBIT = 0;
  return lit;
}

