async function V_WAIT(num = 3, who = false, int = false) {
  let val = 0;
  g.WHO_WAIT = 0;
  if (!int) {
    tell("Time passes...\n");
  }
  loop1: for (;;) {
    if ((num = num - 1) < 0) {
      break loop1;
    } else if (val = await CLOCKER()) {
      if (val == M_FATAL) {
        break loop1;
      } else if ((who == GLOBAL_DUFFY) && !g.FINGERPRINT_OBJ) {
        break loop1;
      } else if (who && (loc(who) == g.HERE)) {
        tell(D(who), ", for whom you are waiting, has arrived.\n");
        break loop1;
      } else {
        g.WHO_WAIT = g.WHO_WAIT + 1;
        if (!(eq(getb(0, 1) & 16, 0))) {
          tell("(");
          await TIME_PRINT(g.PRESENT_TIME);
          tell(") ");
        }
        if (int) {
          tell("Do you want to continue what you were doing? (Y/N)");
        } else {
          tell("Do you want to keep waiting? (Y/N)");
        }
        if (!(await YES$())) {
          break loop1;
        } else {
        }
      }
    } else if ((who == GLOBAL_DUFFY) && !g.FINGERPRINT_OBJ) {
      break loop1;
    } else if (who && (loc(who) == g.HERE)) {
      tell(D(who), ", for whom you are waiting, has arrived.\n");
      break loop1;
    } else if (who && ((g.WHO_WAIT = g.WHO_WAIT + 1) > 30)) {
      tell(D(who), " still hasn't arrived. Do you want to keep waiting? (Y/N) ");
      if (!(await YES$())) {
        break loop1;
      }
      g.WHO_WAIT = 0;
    } else {
    }
  }
  g.CLOCK_WAIT = true;
  if (!int) {
    await V_TIME();
  }
  return true;
}

async function INT_WAIT(n_) {
  let tim = 0, req = 0;
  tim = g.PRESENT_TIME;
  await V_WAIT(req = random(n_ * 2), false, true);
  if (!((g.PRESENT_TIME - tim) < req)) {
    return true;
  } else {
    return false;
  }
}

async function V_WAIT_FOR() {
  let who = 0;
  if (g.PRSO == INTNUM) {
    if (g.P_NUMBER > g.PRESENT_TIME) {
      await V_WAIT_UNTIL();
      return true;
    } else if (g.P_NUMBER > 180) {
      tell("That's too long to wait.\n");
      return true;
    } else {
      return await V_WAIT(g.P_NUMBER);
    }
  } else if (g.PRSO == NOON) {
    await V_WAIT_UNTIL();
    return true;
  } else if (g.PRSO == GLOBAL_DUFFY) {
    if (g.FINGERPRINT_OBJ) {
      return await V_WAIT(10000, g.PRSO);
    } else {
      tell("You would wait quite a while, since Sergeant Duffy is always nearby, but never approaches you unless requested.\n");
      return true;
    }
  } else if (hasFlag(g.PRSO, PERSON)) {
    who = get(g.CHARACTER_TABLE, getProp(g.PRSO, P.CHARACTER));
    if (loc(who) == g.HERE) {
      tell("That person is already here!\n");
      return true;
    } else {
      return await V_WAIT(10000, who);
    }
  } else {
    tell("Not a good idea. You might wait all day.\n");
    return true;
  }
}

async function V_WAIT_UNTIL() {
  if (g.PRSO == NOON) {
    g.P_NUMBER = 720;
    g.PRSO = INTNUM;
  } else if (g.P_NUMBER < 8) {
    g.P_NUMBER = (g.P_NUMBER + 12) * 60;
  } else if (g.P_NUMBER < 13) {
    g.P_NUMBER = g.P_NUMBER * 60;
  }
  if (g.PRSO == INTNUM) {
    if (g.P_NUMBER > g.PRESENT_TIME) {
      return await V_WAIT(g.P_NUMBER - g.PRESENT_TIME);
    } else {
      tell("You are clearly ahead of your time.\n");
      return true;
    }
  } else {
    tell("Your sanity is coming into question.\n");
    return true;
  }
}

