async function CORRIDOR_LOOK(itm = false) {
  let c_ = 0, z = 0, cor = 0, val = 0, found = false;
  if (c_ = getProp(g.HERE, P.CORRIDOR)) {
    loop1: for (;;) {
      if (!((z = c_ - 2048) < 0)) {
        cor = g.COR_2048;
      } else if (!((z = c_ - 1024) < 0)) {
        cor = g.COR_1024;
      } else if (!((z = c_ - 512) < 0)) {
        cor = g.COR_512;
      } else if (!((z = c_ - 256) < 0)) {
        cor = g.COR_256;
      } else if (!((z = c_ - 128) < 0)) {
        cor = g.COR_128;
      } else if (!((z = c_ - 64) < 0)) {
        cor = g.COR_64;
      } else if (!((z = c_ - 32) < 0)) {
        cor = g.COR_32;
      } else if (!((z = c_ - 16) < 0)) {
        cor = g.COR_16;
      } else if (!((z = c_ - 8) < 0)) {
        cor = g.COR_8;
      } else if (!((z = c_ - 4) < 0)) {
        cor = g.COR_4;
      } else if (!((z = c_ - 2) < 0)) {
        cor = g.COR_2;
      } else if (!((z = c_ - 1) < 0)) {
        cor = g.COR_1;
      } else {
        break loop1;
      }
      val = await CORRIDOR_CHECK(cor, itm);
      if (!found) {
        found = val;
      }
      c_ = z;
    }
    return found;
  } else {
    return false;
  }
}

async function CORRIDOR_CHECK(cor, itm) {
  let cnt = 2, past = 0, found = false, rm = 0, obj = 0;
  for (;;) {
    if (eq(rm = get(cor, cnt), 0)) {
      return false;
    } else if (rm == g.HERE) {
      past = 1;
    } else if (obj = first(rm)) {
      loop2: for (;;) {
        if (itm) {
          if (obj == itm) {
            found = get(cor, past);
            break loop2;
          }
        } else if (hasFlag(obj, PERSON) && !(await IN_MOTION$(obj))) {
          tell(D(obj), " is ");
          if (eq(getProp(rm, P.LINE), OUTSIDE_LINE_C)) {
            tell("off");
          } else {
            tell("down the hall");
          }
          tell(" to ");
          await DIR_PRINT(get(cor, past));
          tell(".\n");
        }
        obj = next(obj);
        if (!obj) {
          break loop2;
        }
      }
      if (found) {
        return found;
      }
    }
    cnt = cnt + 1;
  }
}

