async function V_CALL() {
  let per = 0, mot = false;
  if (hasFlag(g.PRSO, PERSON)) {
    per = get(g.CHARACTER_TABLE, getProp(g.PRSO, P.CHARACTER));
    if (await IN_MOTION$(per)) {
      mot = true;
    }
    if ((loc(per) == g.HERE) || (await CORRIDOR_LOOK(per))) {
      tell(D(per));
      if (await GRAB_ATTENTION(per)) {
        if (mot) {
          tell(" stops and turns toward you.\n");
          return true;
        } else {
          tell(" is facing you.\n");
          return true;
        }
      } else {
        tell(" takes no notice of your call.\n");
        return true;
      }
    } else {
      tell("You don't see ", D(per), " here.\n");
      return true;
    }
  } else {
    return await V_CALL_LOSE();
  }
}

