async function GROUND_F() {
  if (isVerb(V.BRUSH) && (loc(FRAGMENT) == PLAYER) && !g.FRAGMENT_CLEANED) {
    await PERFORM(V.BRUSH, FRAGMENT);
    return true;
  } else if (isVerb(V.EXAMINE, V.SEARCH, V.SEARCH_AROUND)) {
    if (g.HERE == ROURKE_ROOM) {
      tell("The floor is hardwood.\n");
      return true;
    } else if (g.HERE == FOYER) {
      tell("The floor is marble.\n");
      return true;
    } else if (g.HERE == IN_ROSES) {
      if (!(hasFlag(HOLE, INVISIBLE))) {
        await PERFORM(V.SEARCH_AROUND, HOLE);
        return true;
      } else if (isVerb(V.SEARCH_GROUND_UNDER) && (g.PRSI == BALCONY)) {
        tell("The balcony above is very large. Searching the entire area beneath it would take a great deal of time.\n");
        return true;
      } else {
        tell("There are rows upon rows of roses here. It would take you the best part of a day to search the ground in great detail.\n");
        return true;
      }
    } else {
      tell("You don't find anything new there.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function AIR_F() {
  if (isVerb(V.SMELL)) {
    if (g.HERE == ROSE_GARDEN || g.HERE == IN_ROSES) {
      tell("The smell of roses permeates everything.\n");
      return true;
    } else if (g.HERE == NORTH_LAWN || g.HERE == EAST_LAWN || g.HERE == WEST_LAWN) {
      tell("A breeze carries the faint smell of roses through the air.\n");
      return true;
    } else if (eq(getProp(g.HERE, P.LINE), OUTSIDE_LINE_C)) {
      tell("The air is clear and fresh here.\n");
      return true;
    } else if (await FRESH_AIR$(g.HERE)) {
      return true;
    } else {
      tell("The air is rather musty here.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function FRESH_AIR$(rm) {
  let p_ = 0, l = 0, tx = 0, o = 0;
  p_ = 0;
  for (;;) {
    if ((p_ = nextProp(g.HERE, p_)) == 0) {
      return false;
    } else if (!(p_ < LOW_DIRECTION)) {
      tx = getPropAddr(g.HERE, p_);
      l = propSize(tx);
      if ((l == DEXIT) && hasFlag(o = getb(tx, DEXITOBJ), OPENBIT)) {
        tell("There is a pleasant breeze coming through the ", D(o), ".\n");
        return true;
      }
    }
  }
}

async function LAKE_F() {
  if (isVerb(V.SWIM, V.LEAP, V.THROUGH)) {
    tell("You're not on vacation, but with ideas like that you will probably be given a rather long one.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.EXAMINE)) {
    if ((g.HERE == NORTH_LAWN) && (loc(SOGGY_WILL) == LAKE)) {
      tell("A crumpled piece of paper is floating on the water a few feet from shore. With an uncommonly agile motion, you retrieve the drenched paper.\n");
      return move(SOGGY_WILL, g.WINNER);
    } else {
      tell("Surely you don't suspect the fish also?\n");
      return true;
    }
  } else {
    return false;
  }
}

async function SHED_F() {
  if (isVerb(V.THROUGH)) {
    if (g.HERE == EAST_LAWN || g.HERE == BEHIND_SHED) {
      await GOTO(SHED_ROOM);
      return true;
    } else {
      tell("Senility strikes!\n");
      return true;
    }
  } else if (isVerb(V.LISTEN)) {
    if (!(g.SECRET_MEETING == 0)) {
      tell("You hear two muffled voices inside the shed.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.HIDE_BEHIND)) {
    if (g.HERE == EAST_LAWN) {
      tell("You carefully sneak behind the shed. It seems that no one saw you.\n");
    } else {
      tell("You leave the shed and quietly slip behind it. Nobody appears to have seen you.\n");
    }
    await GOTO(BEHIND_SHED);
    return true;
  } else {
    return false;
  }
}

