async function SHOW_HOLE() {
  tell("McNabb grabs your arm and leads you to a spot deep within the garden and near the house. You might never have found this place alone. He points at the ground, where you see two holes in the soft earth.\n");
  clearFlag(HOLE, INVISIBLE);
  return g.HOLE_SHOWN = true;
}

async function HOLE_F() {
  if (!g.HOLE_TELL) {
    tell("What hole?\n");
    return true;
  } else if (isVerb(V.ASK_ABOUT)) {
    return false;
  } else if (isVerb(V.FIND)) {
    if (!(g.HERE == IN_ROSES)) {
      tell("They're among the roses, or have you forgotten?\n");
      return true;
    } else if (!(hasFlag(HOLE, INVISIBLE))) {
      tell("They're right here!\n");
      return true;
    } else if (!g.HOLE_SHOWN && (80 > random(100))) {
      tell("The rose garden is vast and full of thorny roses. You might look for the rest of the day before you find them.\n");
      return true;
    } else {
      tell("The garden is rather big, even just the area you are searching now, and the holes were small. They're not here, but are probably nearby.\n");
      return true;
    }
  } else if (HOLE == g.PRSI || HOLE == g.PRSO) {
    if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
      tell("There are two holes here, each about two inches by four inches. They are at least three inches deep and the soil is compacted around them.\n");
      return true;
    } else if ((isVerb(V.SEARCH_GROUND_AROUND) && (g.PRSO == GROUND)) || isVerb(V.SEARCH_AROUND)) {
      if (eq(loc(GARDENER), g.HERE)) {
        tell("Mr. McNabb watches you with ill-concealed irritation.\n");
      }
      if (g.FRAGMENT_FOUND) {
        tell("Aside from dirt, organic fertilizer, and small crawly creatures, you turn up nothing but roses.\n");
        return true;
      } else if (((g.RST = g.RST + 1) > 2) || (30 > random(100))) {
        tell("Ouch! You cut your finger on a sharp edge as you dig. You search carefully in the dirt, now that you are sure something is there, and pull up a piece of porcelain, covered with dirt and dried mud.\n");
        await THIS_IS_IT(FRAGMENT);
        move(FRAGMENT, g.WINNER);
        clearFlag(FRAGMENT, INVISIBLE);
        g.FRAGMENT_FOUND = true;
        return g.FRAGMENT_FELT = true;
      } else {
        tell(S(get(g.ROSE_DIGS, g.RST)), "\n");
        return true;
      }
    } else {
      return false;
    }
  } else {
    tell("There is no hole here.\n");
    return true;
  }
}

async function FRAGMENT_F() {
  if (isVerb(V.EXAMINE)) {
    if (g.FRAGMENT_CLEANED) {
      tell("The fragment is beautifully hand-painted");
      g.FRAGMENT_FLAG = true;
      if (g.CHINA_EXAMINED) {
        tell(", exactly like those you saw in the kitchen");
      }
      tell(".\n");
      return true;
    } else {
      tell("The piece of porcelain is filthy, coated with dried mud. You can barely make out some design underneath the dirt.\n");
      return true;
    }
  } else if (isVerb(V.FINGERPRINT)) {
    tell("It's covered with dirt and mud. You realize that there would be no good fingerprints on it.\n");
    return true;
  } else if (isVerb(V.ANALYZE)) {
    return await DO_ANALYZE();
  } else if (isVerb(V.BRUSH)) {
    g.FRAGMENT_CLEANED = true;
    tell("As you wipe off the piece of porcelain, you notice that it is a fragment of some very beautiful piece, handsomely painted.");
    if (g.CHINA_EXAMINED) {
      tell("  The markings are identical to those you saw on the china in the kitchen.");
    }
    return crlf();
  } else {
    return false;
  }
}

