async function I_CALL() {
  let mrl = loc(MRS_ROBNER);
  if (g.CALL_RING) {
    if (mrl == LIVING_ROOM) {
      g.CALL_RING = false;
      if (g.HERE == LIVING_ROOM) {
        tell("Mrs. Robner picks up the phone. \"Oh, hi. Look, I can't talk now. I'll call you later, okay? Bye, then.\" She hangs up the phone.\n");
        await ROBNER_CALL_MOVE();
        return true;
      }
      await ROBNER_CALL_MOVE();
      return false;
    } else {
      tell("The phone rings again.\n");
      if (await GLOBAL_IN$(TELEPHONE, g.HERE)) {
        await THIS_IS_IT(TELEPHONE);
      }
      return true;
    }
  }
  if (g.CALL_IN_PROGRESS) {
    if ((g.CALL_IN_PROGRESS = g.CALL_IN_PROGRESS + 1) > 15) {
      g.CALL_IN_PROGRESS = false;
      await QUEUE(I_CALL.id, 0);
      await UNPRIORITIZE(MRS_ROBNER);
      return false;
    } else if (hasFlag(MASTER_BEDROOM_DOOR, OPENBIT) || (g.HERE == MASTER_BEDROOM)) {
      tell("Mrs. Robner speaks quietly into the phone and hangs up.\n");
      g.CALL_IN_PROGRESS = false;
      await QUEUE(I_CALL.id, 0);
      await UNPRIORITIZE(MRS_ROBNER);
      return true;
    } else {
      return false;
    }
  } else if (g.CALL_WAITING) {
    if (g.HERE == mrl || g.HERE == MASTER_BATH || g.HERE == BEDROOM_BALCONY) {
      if (!((g.CALL_WAITING = g.CALL_WAITING + 1) > 3)) {
        tell("Mrs. Robner glares at you, holding the phone in one hand. \"Would you mind terribly?\", she asks.\n");
        return true;
      } else if (g.CALL_MOVE) {
        tell("\"I can't understand why you won't let me use the phone. Can't I talk to my best friend? Hummph...I suppose it can wait, since you are being so...uh...unhelpful.\" She puts down the receiver, rises from her bed, and starts to leave.\n");
        g.CALL_MOVE = false;
        g.CALL_WAITING = false;
        await QUEUE(I_CALL.id, 0);
        return await UNPRIORITIZE(MRS_ROBNER);
      } else {
        tell("\"I give up. What IS your problem, anyway?,\" Mrs. Robner asks, in a barely controllable rage. \"I'll call you back,\" she says, and slams down the receiver.\n");
        g.CALL_MOVE = false;
        await QUEUE(I_CALL.id, 0);
        return await UNPRIORITIZE(MRS_ROBNER);
      }
    } else {
      await ESTABLISH_CALL();
      return false;
    }
  } else if (g.CALL_MOVE) {
    if (mrl == MASTER_BEDROOM) {
      if (g.HERE == BEDROOM_BALCONY || g.HERE == MASTER_BATH || g.HERE == MASTER_BEDROOM) {
        if (!(g.HERE == MASTER_BEDROOM)) {
          tell("Mrs. Robner enters her bedroom and spots you.\n");
        }
        tell("\"I'd like to make a private phone call, if you have no objection,\" she says. She motions toward the door.\n");
        return g.CALL_WAITING = 1;
      } else {
        await ESTABLISH_CALL();
        return false;
      }
    } else {
      return false;
    }
  } else if (g.HERE == LIBRARY || g.HERE == LIVING_ROOM || g.HERE == MASTER_BEDROOM) {
    tell("The telephone rings.\n");
    await THIS_IS_IT(TELEPHONE);
    await ESTABLISH_GOAL(MRS_ROBNER, LIVING_ROOM, true);
    g.CALL_RING = true;
    return await QUEUE(I_CALL.id, -1);
  } else if (g.HERE == mrl) {
    tell("You can hear a telephone ringing in a nearby room. Mrs. Robner says \"Pardon me\" and starts for the door.\n");
    g.CALL_RING = true;
    await QUEUE(I_CALL.id, -1);
    return await ESTABLISH_GOAL(MRS_ROBNER, LIVING_ROOM, true);
  } else {
    if (!(eq(getProp(g.HERE, P.LINE), OUTSIDE_LINE_C))) {
      tell("You hear a phone ringing in a nearby room.\n");
      g.CALL_RING = true;
      await QUEUE(I_CALL.id, -1);
      return await ESTABLISH_GOAL(MRS_ROBNER, LIVING_ROOM, true);
    } else if (50 > random(100)) {
      tell("You notice a very faint ringing sound coming from the house.\n");
      await ROBNER_CALL_MOVE();
      return true;
    } else {
      return false;
    }
  }
}

async function THIS_IS_IT(obj) {
  g.P_IT_OBJECT = obj;
  return g.P_IT_LOC = g.HERE;
}

async function ESTABLISH_CALL() {
  let cor = 0;
  g.CALL_MOVE = false;
  g.CALL_IN_PROGRESS = 1;
  clearFlag(MASTER_BEDROOM_DOOR, OPENBIT);
  if (g.HERE == CORRIDOR_1) {
    tell("Mrs. Robner shuts the door to the master bedroom.\n");
    return true;
  } else if (g.HERE == CORRIDOR_2 || g.HERE == STAIR_TOP) {
    tell("You hear the master bedroom door shut.\n");
    return true;
  } else {
    return false;
  }
}

async function MASTER_BEDROOM_DOOR_F() {
  if (isVerb(V.LISTEN) && g.CALL_IN_PROGRESS) {
    tell("You can hear the muffled voice of Mrs. Robner through the door.\n");
    return true;
  } else if (isVerb(V.KNOCK)) {
    if (g.CALL_IN_PROGRESS) {
      tell("Mrs. Robner's calls out. \"Wait just one minute!\"\n");
      return true;
    } else {
      return await DOOR_F();
    }
  } else {
    return false;
  }
}

async function DOOR_F() {
  if (isVerb(V.LISTEN)) {
    tell("You can't hear anything through the door.\n");
    return true;
  } else if (isVerb(V.KNOCK)) {
    if ((g.PRSO == FRONT_DOOR) && !g.WELCOMED && (g.PRESENT_TIME < 700) && (g.HERE == FRONT_PATH)) {
      tell("You hear footsteps inside the house. Mrs. Robner, dressed in black, opens the door and greets you.\n");
      return await WELCOME();
    } else if (await INHABITED$(await DOOR_ROOM())) {
      tell("A muffled voice says, \"Come in!\"\n");
      return true;
    } else {
      tell("There is no answer at the door.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function WELCOME() {
  tell("\"Hello,\" she says, \"I'm Mrs. Robner. Please come in. I'm afraid I really can't help you much. This is surely a terrible waste of time, not to mention upsetting, having all these police marching around the house. This has been a trying time, as I suppose you can understand. As I told Mr. Coates and the other detective, you may look around but you must be out by 8 o'clock at the latest. Oh, I almost forgot...Mr. Coates will be reading my husband's will at noon in the living room. You may attend if you wish.\"");
  g.WELCOMED = true;
  remove(MRS_ROBNER);
  if (g.HERE == FRONT_PATH) {
    crlf();
    tell("Mrs. Robner leads you into the house and closes the door behind you.\n");
    crlf();
    await GOTO(FOYER);
  }
  move(MRS_ROBNER, FOYER);
  tell("\"I'm going to make myself some breakfast now. I'll be around all day if you need anything. I'll do what I can to help. Good day!\"\n");
  clearFlag(FRONT_DOOR, OPENBIT);
  return await ESTABLISH_GOAL(MRS_ROBNER, KITCHEN);
}

async function INHABITED$(rm) {
  let f = 0;
  if (!(f = first(rm))) {
    return false;
  }
  for (;;) {
    if (hasFlag(f, PERSON)) {
      return true;
    }
    f = next(f);
    if (!f) {
      return false;
    }
  }
}

async function DOOR_ROOM() {
  if (g.PRSO == MASTER_BEDROOM_DOOR) {
    return MASTER_BEDROOM;
  } else if (g.PRSO == GEORGE_DOOR) {
    return GEORGE_ROOM;
  } else if (g.PRSO == DUNBAR_DOOR) {
    return DUNBAR_ROOM;
  } else if (g.PRSO == ROURKE_DOOR) {
    return ROURKE_ROOM;
  } else {
    return false;
  }
}

async function ROBNER_CALL_MOVE() {
  g.ROBNER_OLD_LOC = loc(MRS_ROBNER);
  await ESTABLISH_GOAL(MRS_ROBNER, MASTER_BEDROOM, true);
  g.CALL_MOVE = true;
  return await QUEUE(I_CALL.id, -1);
}

async function TELEPHONE_F() {
  if (!(g.HERE == LIBRARY || g.HERE == MASTER_BEDROOM || g.HERE == LIVING_ROOM)) {
    tell("There's no telephone here.\n");
    return true;
  } else if (isVerb(V.FIND)) {
    tell("You are the detective, after all.\n");
    return true;
  } else if (isVerb(V.TAKE, V.LISTEN, V.REPLY)) {
    if (g.CALL_RING) {
      tell("You take the phone and hear an unfamiliar man's voice say \"Hello? Is Leslie there?\" You start to reply, but Mrs. Robner");
      if (g.HERE == LIVING_ROOM) {
        tell(" enters and takes the phone from you. \"Thank you, inspector,\" she says, and then into the telephone: \"Hello? Oh, hi. I can't really talk now. I'll call you back soon, OK? Bye.\" She hangs up and starts toward the door.\n");
      } else {
        tell(" picks up the phone from another extension and hears you. \"I've got it, inspector,\" she says. \"Hello? Oh, it's you. I can't talk now. I'll call you back soon. Bye!\" You hear two clicks and the line goes dead.\n");
      }
      g.CALL_RING = false;
      move(MRS_ROBNER, LIVING_ROOM);
      return await ROBNER_CALL_MOVE();
    } else if (g.CALL_IN_PROGRESS) {
      tell("You can hear Mrs. Robner and a man whose voice you don't recognize. Robner: \"...much too early to consider it.\"\nMan's Voice: \"But we couldn't have planned it better. You're free.\"\nRobner: \"Yes, but it will...Wait a second...I think...\"\n\"Click.\" You realize that the call has been disconnected.\n");
      g.CALL_OVERHEARD = true;
      g.CALL_IN_PROGRESS = false;
      await QUEUE(I_CALL.id, 0);
      return await UNPRIORITIZE(MRS_ROBNER);
    } else {
      tell("All you hear is a dial tone.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function ENVELOPE_F() {
  if (isVerb(V.OPEN)) {
    if (eq(loc(MRS_ROBNER), g.HERE)) {
      tell("Mrs. Robner grabs the envelope from you. \"That,\" she says, \"is none of your business!\"\n");
      move(ENVELOPE, MRS_ROBNER);
      return true;
    }
    g.ENVELOPE_OPENED = true;
    if (!(loc(ENVELOPE) == g.WINNER) && (await ITAKE(false))) {
      tell("(Taken)\n");
    }
    return false;
  } else if (isVerb(V.CLOSE) && g.ENVELOPE_OPENED) {
    tell("You close the envelope carefully, but it still looks like it has been opened.\n");
    clearFlag(ENVELOPE, OPENBIT);
    return true;
  } else {
    return false;
  }
}

async function IN_MOTION$(person) {
  let gt = 0;
  gt = get(g.GOAL_TABLES, getProp(person, P.CHARACTER));
  if (get(gt, GOAL_ENABLE) && get(gt, GOAL_S) && !(eq(loc(person), get(gt, GOAL_F)))) {
    return true;
  } else {
    return false;
  }
}

async function MRS_ROBNER_F(rarg = false) {
  let $1;
  if (!rarg && isVerb(V.GIVE) && (g.PRSO == ENVELOPE)) {
    await PERFORM(V.SHOW, MRS_ROBNER, ENVELOPE);
    return true;
  }
  if (rarg == M_OBJDESC) {
    if (await IN_MOTION$(MRS_ROBNER)) {
      if (g.CALL_MOVE) {
        tell("Mrs. Robner appears to be in a hurry.\n");
      }
    } else if (g.CALL_WAITING) {
      tell("Mrs. Robner is staring at you.\n");
    } else if (loc(MRS_ROBNER) == KITCHEN) {
      tell("Mrs. Robner is preparing a meal.\n");
    } else if (loc(MRS_ROBNER) == DINING_ROOM) {
      tell("Mrs. Robner is eating breakfast here.\n");
    } else if (loc(MRS_ROBNER) == LIVING_ROOM) {
      if (g.POST_WILL) {
        return true;
      } else {
        tell("Mrs. Robner is sitting here, knitting.\n");
      }
    } else if (loc(MRS_ROBNER) == MASTER_BEDROOM) {
      tell("Mrs. Robner is sitting on her bed.\n");
    } else {
      tell("Mrs. Robner is here.\n");
    }
    return await CARRY_CHECK(MRS_ROBNER);
  } else if (isVerb(V.HELLO, V.GOODBYE)) {
    tell("Mrs. Robner says a curt \"");
    if (isVerb(V.HELLO)) {
      tell("Hello");
    } else {
      tell("Bye");
    }
    tell("\".\n");
    return true;
  } else if (g.WINNER == MRS_ROBNER) {
    if (isVerb(V.FIND)) {
      return false;
    } else if (isVerb(V.OPEN) && (g.PRSO == ENVELOPE)) {
      if (g.ENVELOPE_OPENED) {
        tell("\"You seem to have taken care of that already.\"\n");
        return true;
      } else {
        tell("\"I believe there are laws protecting the privacy of mail. I will not open the envelope for you or anyone else.\"\n");
        return true;
      }
    } else if (await COM_CHECK(MRS_ROBNER)) {
      return true;
    } else {
      $1 = await PICK_ONE(g.WHY_ME);
      tell(S($1));
      tell("\n");
      return true;
    }
  } else if (isVerb(V.ARREST) && (g.ENVELOPE_OPENED || g.CALL_OVERHEARD)) {
    if (!(hasFlag(LAB_REPORT, TOUCHBIT))) {
      await MURDER_NOT_PROVEN(MRS_ROBNER);
      return true;
    }
    tell("Sergeant Duffy enters and leads Mrs. Robner away.\n\n");
    (await END_HEADER("August 2"));
    tell("I am sorry to inform you that the grand jury investigating the murder charge against Mrs. Robner declined to indict her, citing a lack of evidence linking her with the execution of the crime. Please try to be more cautious when making arrests in the future.\n\n\n");
    return await CASE_OVER();
  } else if (isVerb(V.ASK_ABOUT) && (g.PRSO == MRS_ROBNER)) {
    if (!(await GRAB_ATTENTION(MRS_ROBNER))) {
      return true;
    } else if (g.PRSI == GLOBAL_HIDDEN_CLOSET) {
      if (g.HC_ROBNER) {
        tell("\"I'm quite shocked about it. I really had no idea!\"\n");
        return true;
      } else {
        tell("\"I don't know what you're talking about, Inspector. I know of no such closet.\"\n");
        return true;
      }
    } else if (g.PRSI == GLOBAL_ALLERGONE || g.PRSI == ALLERGONE || g.PRSI == ALLERGONE_BOTTLE) {
      tell("\"I have some allergies, Inspector. Simply dreadful in the fall and spring. That's what the Allergone is for. I don't use them much this time of year, though.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_SNEEZO || g.PRSI == SNEEZO || g.PRSI == SNEEZO_BOTTLE) {
      tell("\"Sneezo is a wonderful cold remedy. Whenever I get a cold, I just take a few, and I usually feel much better before long.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_CALL) {
      if (g.CALL_OVERHEARD && g.MR_ENVELOPE) {
        tell("\"I guess you know it was Steven. I admit we were lovers, and we planned to marry if I could get a divorce from Marshall. He refused to consider it, the divorce I mean, even though he had no time for me anymore. He was married to the company, and he refused to see my side of things. Steven was suggesting that now we could marry. I told him I thought the timing was poor, or at least I would have if you hadn't eavesdropped.\"\n");
        return true;
      } else if (g.CALL_OVERHEARD) {
        tell("\"I was talking to a good friend of mine. We were discussing some plans we made; of course they had to be changed, under the circumstances. They are none of your business. They don't concern my husband's suicide at all, I assure you.\"\n");
        return true;
      } else {
        tell("\"It was just a friend of mine, offering his condolences.\"\n");
        return true;
      }
    } else if (g.PRSI == GLOBAL_STEVEN) {
      if (!g.MR_ENVELOPE) {
        tell("\"I don't know who you mean. I have no friend named Steven.\"\n");
        return true;
      } else if (g.CALL_OVERHEARD && g.MR_ENVELOPE) {
        tell("\"I might as well tell you. Steven and I were lovers and we were going to be married if I could divorce Marshall. I asked Marshall about it, but he became angry and refused. I didn't know what to do. Don't look at me that way. I had nothing to do with my husband's death. Driving him to it with talk of divorce? You didn't know Marshall, that's for sure! I should've told the police earlier, I suppose, but it's really none of your business.\"\n");
        return true;
      } else if (g.MR_ENVELOPE) {
        tell("\"Steven is a close personal friend. We have known each other for many years, and I visit his home frequently. Marshall knew of our friendship and didn't begrudge it in the slightest. My husband and I had a very trusting relationship. You may find the idea of trust difficult to understand, I suppose.\"\n");
        return true;
      } else {
        return false;
      }
    } else if (g.PRSI == GLOBAL_MR_ROBNER) {
      tell("\"I loved my husband, no matter what you may think. I am very sorry to have lost him.\" The speech is almost a set piece, and not too convincing.\n");
      return true;
    } else if (g.PRSI == GEORGE || g.PRSI == GLOBAL_GEORGE) {
      await DISCRETION(MRS_ROBNER, GEORGE);
      tell("\"A child. He may be a man in age, but he still hasn't really grown up. He'll find himself someday, but in the meantime he can be a trial. I guess Marshall and I were too lenient. We probably still are, but he is our son, after all. We can't throw him out on the street.\"\n");
      return true;
    } else if (g.PRSI == BAXTER || g.PRSI == GLOBAL_BAXTER) {
      tell("\"Baxter has been my husband's partner for a long time, but they're not close friends. Baxter has always had the head for making money, and Marshall had the creative spark for new products. The two of them were perfect for each other in the early days. Of course, things haven't been going well lately. I guess none of that matters much now.\"\n");
      return true;
    } else if (g.PRSI == CORPSE || g.PRSI == DUNBAR || g.PRSI == GLOBAL_DUNBAR) {
      await DISCRETION(MRS_ROBNER, DUNBAR);
      tell("\"I've always thought she was a bit too smug in her relationships around here. A bit above herself, if you see my meaning. After all, she's really just a glorified secretary. She acts as though she's part of the family, and she does get along well with almost everyone here. I swear, though, Marshall spent more time with her than me, lately. Um...not that I'm trying to imply that anything went on between them. Quite the contrary.\"\n");
      return true;
    } else if (g.PRSI == ROURKE || g.PRSI == GLOBAL_ROURKE) {
      await DISCRETION(MRS_ROBNER, ROURKE);
      tell("\"She's an excellent housekeeper and sometimes even helps with the cooking For all her good qualities, though, she's too much of a snoop and a gossip. She tires to keep track of everyone around here. It's unnerving sometimes. But, as servants go these days, she's quite extraordinary.\"\n");
      return true;
    } else if (g.PRSI == GARDENER || g.PRSI == GLOBAL_GARDENER) {
      tell("\"I don't pay much attention to him. He's worked out well; the grounds are in excellent condition. You must take a look at his roses while you're here. They're really spectacular.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_OLD_WILL) {
      if (g.WILL_TIME > 0) {
        tell("\"It's what I expected, really.\"\n");
        return true;
      } else {
        tell("\"Marshall takes care of that sort of thing. The will, I suppose, leaves the estate to George and me, but I can't be sure.\"\n");
        return true;
      }
    } else if (g.PRSI == NEW_WILL) {
      tell("\"What do you know? Marshall changed the will, after all. Where did you ever find this? What? George was trying to destroy it? I'm shocked. You don't think George had anything to do...\" She stops short.\n");
      return true;
    } else if (g.PRSI == GLOBAL_NEW_WILL) {
      tell("\"If there is a new will, I certainly don't know where it is.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_FOCUS) {
      tell("\"Oh, you mean the \"scandal\"? Focus Corporation was a subsidiary of Robner Corp. some years ago. There was a big to-do about misuse of funds or some such thing, but Marshall kept it pretty quiet. He told me that the people responsible were forced out of the company, but that charges weren't pressed to avoid bad publicity. I didn't realize anyone remembered that.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_SAFE) {
      tell("\"I don't know of a safe in the house, although it's perfectly believable that Marshall has one hidden somewhere. It would appeal to his childish side, I think.\"\n");
      return true;
    } else {
      tell("\"I don't know much about that.\"\n");
      return true;
    }
  } else if (isVerb(V.CONFRONT, V.SHOW)) {
    if (!(await GRAB_ATTENTION(MRS_ROBNER))) {
      return true;
    } else if (g.PRSI == LAB_REPORT) {
      tell("Mrs. Robner reads the report with shocked disbelief. \"I...I don't know what to say. Who would want to kill Marshall? He was so well liked and...\" She breaks down, sobbing.\n");
      return true;
    } else if (g.PRSI == NEW_WILL) {
      tell("Mrs. Robner reads the will. \"That's that, then,\" she says. \"I guess Marshall was pushed too far.\"\n");
      return true;
    } else if (g.PRSI == ENVELOPE || g.PRSI == LETTER) {
      if (!g.ENVELOPE_OPENED) {
        tell("\"Thank you, Inspector. The envelope is for me.\" She takes the envelope from you and examines it briefly.\n");
        move(ENVELOPE, MRS_ROBNER);
        return true;
      }
      g.MR_ENVELOPE = true;
      tell("\"You have certainly stooped to a new low, Inspector. Opening people's mail. I think there are laws against that sort of thing, but I guess you wouldn't know.");
      if (g.CALL_OVERHEARD) {
        tell(" I suppose you also know that Steven is my lover and that we were planning to marry. Don't look so melodramatic: I didn't kill my husband. You think my talk of divorce may have driven him to it? Why don't you leave me alone!\"\n");
        return true;
      } else {
        tell(" In any case, what of it? It's from a friend of mine, an old friend from school. We get together now and then to discuss old times. I don't suppose there is a law against that?\"\n");
        return true;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

