async function CSCP() {
  if (isVerb(V.TAKE, V.RUB, V.MOVE)) {
    tell("These items are very rare and delicate, and were used only by Mr. Robner himself. You shouldn't even be touching them.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("Each one is hand-painted and depicts a scene from Greek mythology.\n");
    return g.CHINA_EXAMINED = true;
  } else if (isVerb(V.MUNG)) {
    if (75 > random(100)) {
      tell("As you reach for the ", D(g.PRSO), ", you think of the pension awaiting you upon retirement. \"Is it worth it?\" you think, to be booted off the force for an impulse of anger and stupidity. Fortunately, you calm your temper.\n");
      return true;
    } else {
      tell("With a sweep of your hand, you smash all of them! Mrs. Rourke runs into the room, screaming.\n");
      return await GONE_CRAZY();
    }
  } else {
    return false;
  }
}

async function GONE_CRAZY() {
  tell("Your mind becomes confused amidst strange screaming, yelling, and the pangs of your conscience. \"How could I have done it?\" you ask yourself, as you hear the distant sound of police sirens. Sergeant Duffy and two other officers enter and grab you rather unceremoniously. They take you to a waiting car, where, forlorn and disgusted, you begin to ponder prison life. \"Perhaps,\" you think, \"I shouldn't have done that.\"\n");
  return await CASE_OVER();
}

