async function POPULATION(rm, pr_ = false) {
  let cnt = 0, obj = 0;
  if (!(obj = first(rm))) {
    return cnt;
  }
  for (;;) {
    if (hasFlag(obj, PERSON)) {
      cnt = cnt + 1;
      if (pr_) {
        (await DESCRIBE_PERSON(obj, "there"));
      }
    }
    obj = next(obj);
    if (!obj) {
      return cnt;
    }
  }
}

