async function WINDOW_SHOP(rm, str) {
  let p_ = (await POPULATION(rm));
  if (p_ == 0) {
    crlf();
    return true;
  } else {
    tell(" You can vaguely see ");
  }
  if (p_ == 1) {
    tell("someone");
  } else {
    printN(p_);
    tell(" people");
  }
  tell(" inside the ", S(str), ".\n");
  return true;
}

