async function DUNBAR_F(rarg = false) {
  let $1;
  if (rarg == M_OBJDESC) {
    if (await IN_MOTION$(DUNBAR)) {
      return true;
    } else if ((loc(BAXTER) == SHED) && !(g.SECRET_MEETING == 0)) {
      return true;
    } else if (g.DUNBAR_BAXTER_MEET) {
      return true;
    } else if (loc(DUNBAR) == DUNBAR_BATH) {
      tell("Ms. Dunbar is here, brushing her hair.");
    } else if (loc(DUNBAR) == DUNBAR_ROOM) {
      tell("Ms. Dunbar is lying on her bed.");
    } else if (loc(DUNBAR) == LIVING_ROOM) {
      if (g.POST_WILL) {
        tell("Ms. Dunbar is standing in the corner, looking pensive.");
      } else {
        tell("Ms. Dunbar is sitting on the sofa here.");
      }
    } else {
      tell("Ms. Dunbar is here.");
    }
    crlf();
    await CARRY_CHECK(DUNBAR);
    return true;
  } else if (g.WINNER == DUNBAR) {
    if (isVerb(V.FIND)) {
      return false;
    } else if (await COM_CHECK(DUNBAR)) {
      return true;
    } else if (isVerb(V.HELLO, V.GOODBYE)) {
      tell("Ms. Dunbar nods at you.\n");
      return true;
    } else {
      $1 = await PICK_ONE(g.WHY_ME);
      tell(S($1));
      tell("\n");
      return true;
    }
  } else if (isVerb(V.HELLO, V.ASK_ABOUT, V.SHOW) && !(await GRAB_ATTENTION(DUNBAR))) {
    return true;
  }
  if (isVerb(V.HELLO)) {
    tell("Ms. Dunbar nods at you.\n");
    return true;
  } else if (isVerb(V.ASK_ABOUT) && (g.PRSO == DUNBAR)) {
    if (g.PRSI == GLOBAL_CONCERT) {
      if (g.STUB_D || g.STUB_DX) {
        tell("\"It was an excellent concert, Inspector, but I don't see why you're asking about it.\"\n");
        return true;
      } else {
        tell("\"I don't know what you are talking about. I don't go in for concerts much, you know.\"\n");
        return true;
      }
    } else if (g.PRSI == STUB) {
      if (g.STUB_BX) {
        tell("\"Why, it's just as Mr. Baxter said.\"\n");
        return true;
      } else {
        g.STUB_D = true;
        if (loc(BAXTER) == g.HERE) {
          g.STUB_DX = true;
        }
        if (g.STUB_B) {
          g.CONTRADICTION = true;
        }
        tell("\"Oh, I...well, I guess I should tell you. You see, Mr. Baxter and I, we go together to concerts, only occasionally, you understand. We went that night, the night Marshall died. Then he took me home and that's it. I should have said something before, but I just didn't think it was important, and, well, I didn't think that the others should know we were seeing each other socially. Our...nobody knows about it, you know. Please don't say anything!\"\n");
        return true;
      }
    } else if (g.PRSI == BAXTER || g.PRSI == GLOBAL_BAXTER) {
      tell("\"Mr. Baxter? I see him often when he comes here on business, but I don't really know him that well. We keep to business when he comes around, and I hardly ever talk with him otherwise. He is, of course, an excellent executive, and poor Mr. Robner had every confidence in him.\"\n");
      return true;
    } else if (g.PRSI == LOBLO || g.PRSI == GLOBAL_LOBLO || g.PRSI == LOBLO_BOTTLE) {
      if (g.LOBLO_FLAG) {
        tell("Ms. Dunbar is taken aback. \"I...I don't really know what to say. I take the tablets for my blood pressure. I have for a few months now. I know what you're thinking. I can't understand. Someone must have taken my pills and poisoned Mr. Robner. That's it. It's probably George. He knew about my pills. He's always snooping around. He used to talk about how half the money would be his someday.\"\n");
        return true;
      } else {
        tell("Ms. Dunbar seems a bit surprised. \"You found those in my bathroom, didn't you? I've been taking them for months for my blood pressure. Are they important?\" she asks.\n");
        return true;
      }
    } else if (g.PRSI == GEORGE || g.PRSI == GLOBAL_GEORGE) {
      await DISCRETION(DUNBAR, GEORGE);
      tell("\"Nobody likes George much. He's always alone when he's here, and that's only when he can't get more money to waste. I think he's just been waiting for the day when his father's money would be his. I can't say I miss him when he's not here: A thoroughly obnoxious child.\"\n");
      return true;
    } else if (g.PRSI == MRS_ROBNER || g.PRSI == GLOBAL_MRS_ROBNER) {
      tell("\"She's a lovely person. She and Marshall were always an odd couple: he was so quiet and reserved, and she's so lively and sociable. She's changed a lot over the last few years. She used to enjoy her life here, but lately she's been restless and irritable, and now with Marshall's death, I'm worried about what may become of her.\"\n");
      return true;
    } else if (g.PRSI == ROURKE || g.PRSI == GLOBAL_ROURKE) {
      tell("\"Mrs. Rourke is a very good servant. Always helpful, and always nearby when needed.\"\n");
      return true;
    } else if (g.PRSI == GARDENER || g.PRSI == GLOBAL_GARDENER) {
      tell("\"He seems nice, if you can talk to him. You usually can't, really.\" She laughs briefly. \"Don't ever disturb his roses, or you'll learn the meaning of temper.\" She giggles again.\n");
      return true;
    } else if (g.PRSI == GLOBAL_OLD_WILL) {
      tell("\"I really don't know too much about Marshall's personal business.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_NEW_WILL) {
      if (g.WILL_TIME > 0) {
        tell("\"I don't know anything about it. I suppose Marshall could have written a new will, but I probably would have seen signs of it around the library.\"\n");
        return true;
      } else {
        tell("\"As far as I know, there was no new will written, although Marshall did threaten to disinherit George. I guess he could have written one without my knowledge. I'm not always with him, you know.\"\n");
        return true;
      }
    } else if (g.PRSI == NEW_WILL) {
      tell("Ms. Dunbar reads the will carefully, nodding slowly. \"I guess I'm not surprised that Marshall disinherited George. He's been asking for it.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_MR_ROBNER) {
      tell("Ms. Dunbar looks down at the ground and sniffles softly. \"I've known him for years. He's been tremendously nervous and depressed lately about business. I don't think all was well in his personal life either. George has always been a problem for him. He even mentioned suicide once, although I never took it seriously. It shows you can never tell.\" She wipes her eyes with her hands.\n");
      return true;
    } else if (g.PRSI == GLOBAL_FOCUS) {
      tell("\"Focus? There was once a subsidiary of Robner Corp. with that name. I can't recall much about it, though.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_SAFE) {
      tell("\"A safe? I don't think there's one in the house, although there's one at the office.\"\n");
      return true;
    } else {
      tell("\"I'm sorry, but I can't help you with that.\"\n");
      return true;
    }
  } else if (isVerb(V.SHOW, V.CONFRONT)) {
    if (g.PRSI == STUB) {
      await PERFORM(V.ASK_ABOUT, DUNBAR, STUB);
      return true;
    } else if (g.PRSI == LOBLO) {
      tell("She glances at the pills. \"They're my pills. You must have taken them from my bathroom. Well, what am I supposed to say?\" She looks away.\n");
      return true;
    } else if (g.PRSI == LAB_REPORT) {
      tell("She seems stunned but recovers quickly. \"He didn't commit suicide, then?\" she says. \"But LoBlo, that's a pill I take for my blood pressure.\" She pauses. \"I can tell what you're thinking, but I didn't, couldn't have done it. Why should I? Someone must have taken them, maybe George. He knew I used them.\"\n");
      enable(await QUEUE(I_DUNBAR_ACTIVATE.id, 5 + random(15)));
      return g.LOBLO_FLAG = true;
    } else {
      return false;
    }
  } else if (isVerb(V.ACCUSE)) {
    if (g.LOBLO_FLAG) {
      tell("\"No! I didn't do it! I've worked for Mr. Robner for years. What possible motive could I have?\" With that, Ms. Dunbar begins to cry and move about the room quite nervously.\n");
      return await DUNBAR_SEQUENCE();
    } else {
      tell("\"What?\" she cries. \"Murder?\" She regains her composure and asks, \"I thought he committed suicide, with his medicine.\"\n");
      return true;
    }
  } else if (isVerb(V.ARREST)) {
    if (!(hasFlag(LAB_REPORT, TOUCHBIT))) {
      await MURDER_NOT_PROVEN(DUNBAR);
      return true;
    }
    tell("Sergeant Duffy enters the room solemnly. He places handcuffs on Ms. Dunbar and leads her off. She is sobbing hysterically.\n\n");
    (await END_HEADER("August 10"));
    if (g.MEETING_INTERRUPTED) {
      tell("What a tragedy! Ms. Dunbar, released on bail during her trial for the murder of Mr. Robner, was found dead this morning, the victim of an apparent suicide. Her death is all the more distressing as the district attorney was trying to arrange some plea-bargaining deal with her in exchange for information implicating an unnamed accomplice. I am sorry to be the one to let you know. Thanks for your hard work on the Robner case.\n\n");
    } else {
      tell("I wanted to let you know the disposition of the Robner case. Ms. Dunbar was acquitted today, the jury citing a lack of motive and only circumstantial evidence. I am extremely sorry.\n\n");
    }
    return await CASE_OVER();
  } else {
    return false;
  }
}

