async function DUNBAR_SEQUENCE() {
  let bl = loc(BAXTER);
  if (g.DUNBAR_ACCUSED) {
    return false;
  }
  if (!(loc(DUNBAR) == bl)) {
    await ESTABLISH_GOAL(DUNBAR, bl, true);
  }
  g.DUNBAR_ACCUSED = true;
  g.D_S_BAXTER_LOC = bl;
  return enable(await QUEUE(I_DUNBAR_SEQ.id, -1));
}

async function I_DUNBAR_SEQ() {
  let bl = loc(BAXTER);
  if (!(bl == g.D_S_BAXTER_LOC)) {
    await DUNBAR_SEQUENCE();
    return false;
  } else if (eq(loc(DUNBAR), bl)) {
    put(get(g.GOAL_TABLES, BAXTER_C), GOAL_ENABLE, false);
    if (g.HERE == bl) {
      tell("Ms. Dunbar glances at Baxter and then at you.\n");
      return true;
    } else {
      g.DUNBAR_BAXTER_MEET = true;
      put(get(g.GOAL_TABLES, BAXTER_C), GOAL_ENABLE, true);
      await QUEUE(I_DUNBAR_SEQ.id, 0);
      enable(await QUEUE(I_DUNBAR_SEQ_2.id, 5));
      return false;
    }
  } else {
    return false;
  }
}

async function I_DUNBAR_SEQ_2() {
  g.DUNBAR_BAXTER_MEET = false;
  await ESTABLISH_GOAL(DUNBAR, SHED_ROOM, true);
  enable(await QUEUE(I_DUNBAR_SEQ_D.id, -1));
  enable(await QUEUE(I_DUNBAR_SEQ_3.id, 10));
  return false;
}

async function I_DUNBAR_SEQ_3() {
  await ESTABLISH_GOAL(BAXTER, NORTH_LAWN, true);
  enable(await QUEUE(I_DUNBAR_SEQ_B.id, -1));
  return false;
}

async function I_DUNBAR_SEQ_D() {
  let gt = 0;
  gt = get(g.GOAL_TABLES, DUNBAR_C);
  if (eq(loc(DUNBAR), SHED_ROOM)) {
    if (eq(loc(BAXTER), SHED_ROOM)) {
      enable(await QUEUE(I_DUNBAR_SEQ_4.id, -1));
      await QUEUE(I_DUNBAR_SEQ_D.id, 0);
    } else if (g.HERE == SHED_ROOM) {
      if (50 > random(100)) {
        tell("Dunbar paces around the shed nervously. If she was looking for something, she would have found it by now.\n");
      } else {
        tell("Ms. Dunbar seems to be looking around for something.\n");
      }
      return true;
    }
    return false;
  } else if (eq(getProp(g.HERE, P.LINE), OUTSIDE_LINE_C) && (await FOLLOWED$(DUNBAR))) {
    if (get(gt, GOAL_ENABLE)) {
      put(gt, GOAL_ENABLE, false);
    } else if (28 > random(100)) {
      tell("Ms. Dunbar eyes you nervously.\n");
      return true;
    } else if (50 > random(100)) {
      tell("Ms. Dunbar stares off toward the south.\n");
      return true;
    } else {
      tell("Ms. Dunbar seems to be deep in thought.\n");
      return true;
    }
    if (!g.STUB_DROPPED && eq(getProp(g.HERE, P.LINE), OUTSIDE_LINE_C)) {
      tell("Ms. Dunbar spots you and stops. She reaches into her pocket and pulls out a cigarette. As she does so, what appears to be a ticket stub falls out of her pocket and floats to the ground. She checks her pocket again, apparently for a match, but finds none and puts the cigarette back in her pocket.\n");
      move(STUB, loc(DUNBAR));
      return g.STUB_DROPPED = true;
    } else if (15 > random(100)) {
      tell("Ms. Dunbar glances around as she walks. She takes a quick glance in your direction, but it doesn't seem like she noticed you.\n");
      return put(gt, GOAL_ENABLE, true);
    } else if (50 > random(100)) {
      tell("Ms. Dunbar looks around as she walks and does a brief double-take when she looks in your direction. She slows down and stops.\n");
      return true;
    } else {
      tell("Ms. Dunbar, who has been looking from side to side as she goes, comes to a stop. She spins around, looking in all directions.\n");
      return true;
    }
  } else {
    put(gt, GOAL_ENABLE, true);
    return false;
  }
}

async function I_DUNBAR_SEQ_B() {
  if (eq(loc(BAXTER), NORTH_LAWN) || eq(getProp(g.HERE, P.LINE), TOP_OF_THE_LINE_C)) {
    await QUEUE(I_DUNBAR_SEQ_B.id, 0);
    await ESTABLISH_GOAL(BAXTER, SHED_ROOM, true);
    enable(await QUEUE(I_DUNBAR_SEQ_B_2.id, -1));
  }
  return false;
}

async function I_DUNBAR_SEQ_B_2() {
  let gt = 0;
  gt = get(g.GOAL_TABLES, BAXTER_C);
  if (eq(loc(BAXTER), SHED_ROOM)) {
    await QUEUE(I_DUNBAR_SEQ_B_2.id, 0);
    return false;
  } else if (await FOLLOWED$(BAXTER)) {
    if (get(gt, GOAL_ENABLE)) {
      put(gt, GOAL_ENABLE, false);
      return false;
    } else if (50 > random(100)) {
      tell("Baxter draws a deep breath and looks about contentedly.\n");
      return true;
    } else {
      tell("Baxter stares out over the lake.\n");
      return true;
    }
    if (50 > random(100)) {
      tell("Baxter walks slowly, but with determination. He looks around often, as if he were a prospective buyer of the property. He stops now, staring up at the sky.\n");
      return true;
    } else {
      tell("Baxter stops, bends down, and ties his shoe.");
      if (30 > random(100)) {
        tell("  As he finishes, he takes stands up, and stares at some distant trees.\n");
        return true;
      } else {
        tell(" He stands up and stares off to the south.\n");
        return true;
      }
    }
  } else {
    put(gt, GOAL_ENABLE, true);
    return false;
  }
}

async function I_DUNBAR_SEQ_4() {
  if (g.HERE == SHED_ROOM) {
    if ((g.SECRET_MEETING < 2) || (g.SECRET_MEETING > 5)) {
      tell("You seem to have walked in on some sort of get-together, although from the look on Ms. Dunbar's face, you are not the guest of honor. She is aghast, and she continually looks back and forth between Mr. Baxter and yourself.\n");
    } else {
      tell("As you enter the shed, Mr. Baxter and Ms. Dunbar, who were in the midst of a quiet but heated argument, stop at once. Ms. Dunbar is quite upset and clutches Mr. Baxter. Baxter, who has retained his composure throughout, attempts to comfort Dunbar. She pushes him away and runs out of the shed.\n");
      move(DUNBAR, EAST_LAWN);
      put(get(g.WHERE_TABLES, DUNBAR_C), 0, g.PRESENT_TIME);
      put(get(g.WHERE_TABLES, 0), DUNBAR_C, g.PRESENT_TIME);
    }
    await HEAD_FOR_CLIMAX();
    return true;
  } else if (eq(loc(BAXTER), SHED_ROOM)) {
    if ((g.SECRET_MEETING = g.SECRET_MEETING + 1) > 5) {
      await HEAD_FOR_CLIMAX();
    }
    return false;
  } else {
    return false;
  }
}

async function FOLLOWED$(person) {
  let l = loc(person);
  if (l == g.HERE) {
    return true;
  } else if (g.HERE == GUEST_ROOM) {
    return false;
  } else if (!(eq(getProp(l, P.CORRIDOR) & getProp(g.HERE, P.CORRIDOR), 0))) {
    return true;
  } else {
    return false;
  }
}

async function HEAD_FOR_CLIMAX() {
  if (g.HERE == EAST_LAWN || g.HERE == EAST_SIDE || g.HERE == EAST_OF_DOOR) {
    tell("Baxter and Dunbar both leave the shed, heading off in different directions.\n");
  } else if (g.HERE == BEHIND_SHED) {
    tell("The voices stop and you hear sets of footsteps leaving the shed.\n");
  }
  await ESTABLISH_GOAL(DUNBAR, DUNBAR_ROOM, true);
  await ESTABLISH_GOAL(BAXTER, NORTH_LAWN, true);
  enable(await QUEUE(I_BAXTER_SEQ.id, -1));
  await QUEUE(I_DUNBAR_SEQ_4.id, 0);
  g.MEETING_INTERRUPTED = g.SECRET_MEETING;
  return g.SECRET_MEETING = 0;
}

async function I_BAXTER_SEQ() {
  if (g.BAXTER_SEQ_LOC == MASTER_BEDROOM) {
    if (!(eq(getProp(g.HERE, P.CORRIDOR) & 1, 1)) && !(g.HERE == STAIRS || g.HERE == STAIR_BOTTOM || g.HERE == DUNBAR_ROOM)) {
      g.BAXTER_SEQ_LOC = BEDROOM_BALCONY;
      move(BAXTER, BEDROOM_BALCONY);
      remove(DUNBAR);
      g.DUNBAR_DEAD = true;
      disable(await INT(I_DUNBAR.id));
      move(PISTOL, DUNBAR_ROOM);
      move(SUICIDE_NOTE, DUNBAR_ROOM);
      move(CORPSE, DUNBAR_ROOM);
      await QUEUE(I_BAXTER_SEQ.id, 0);
      enable(await QUEUE(I_BAXTER_ESCAPE.id, -1));
      if (eq(getProp(g.HERE, P.LINE), TOP_OF_THE_LINE_C)) {
        g.SHOT_FIRED = true;
        tell("You hear a pistol shot close by.\n");
      } else if (eq(getProp(g.HERE, P.LINE), OUTSIDE_LINE_C)) {
        tell("You hear what sounds like a pistol shot from inside the house.\n");
      } else {
        tell("From upstairs, you hear a single explosion like a pistol shot.\n");
      }
      await SHOT_FIRED_F();
      return true;
    } else {
      return false;
    }
  } else if (g.BAXTER_SEQ_LOC == BEDROOM_BALCONY) {
    if (!(g.HERE == MASTER_BEDROOM) && !(eq(loc(MRS_ROBNER), MASTER_BEDROOM))) {
      move(BAXTER, MASTER_BEDROOM);
      g.BAXTER_SEQ_LOC = MASTER_BEDROOM;
    }
    return false;
  } else if (g.BAXTER_SEQ_LOC == NORTH_LAWN) {
    if ((loc(DUNBAR) == DUNBAR_ROOM) && !(eq(getProp(g.HERE, P.LINE), OUTSIDE_LINE_C)) && !(g.HERE == BEDROOM_BALCONY)) {
      g.LADDER_FLAG_2 = true;
      g.LADDER_FLAG = false;
      move(LADDER, ORCHARD);
      clearFlag(LADDER, NDESCBIT);
      setFlag(LADDER, TOUCHBIT);
      move(BAXTER, BEDROOM_BALCONY);
      g.BAXTER_SEQ_LOC = BEDROOM_BALCONY;
    }
    return false;
  } else if (loc(BAXTER) == NORTH_LAWN) {
    g.BAXTER_SEQ_LOC = NORTH_LAWN;
    return false;
  } else {
    return false;
  }
}

async function I_BAXTER_ESCAPE() {
  let flg = false;
  if (g.SHOT_FIRED) {
    g.SHOT_FIRED = false;
    if (g.HERE == CORRIDOR_4 || g.HERE == CORRIDOR_3) {
      tell("As you enter the hallway, you catch a glimpse of someone running across the eastern end of the hallway from south to north.\n");
      flg = true;
    } else if (g.HERE == MASTER_BEDROOM) {
      tell("As you walk into the bedroom, you see Baxter running past you to the balcony. He doesn't seem to have noticed you.\n");
      flg = true;
      g.BAXTER_SEEN = true;
    } else if (eq(getProp(g.HERE, P.CORRIDOR) & 1, 1)) {
      tell("As you enter the hallway, you see Baxter running from Dunbar's room across the hall to the master bedroom.\n");
      flg = true;
      g.BAXTER_SEEN = true;
    }
  }
  g.BAXTER_SEQ_LOC = BEDROOM_BALCONY;
  if (g.HERE == ORCHARD || g.HERE == EAST_LAWN || g.HERE == NORTH_LAWN) {
    return flg;
  } else {
    move(BAXTER, IN_ORCHARD);
    g.LADDER_FLAG_2 = false;
    await ESTABLISH_GOAL(BAXTER, DUNBAR_ROOM, true);
    await QUEUE(I_BAXTER_ESCAPE.id, 0);
    g.BAXTER_SEQ_LOC = false;
    return flg;
  }
}

