async function I_SHOT() {
  let flg = false;
  if (loc(MRS_ROBNER) == DUNBAR_ROOM) {
    if (g.HERE == DUNBAR_ROOM) {
      tell("Mrs. Robner, standing quietly by the body, starts sobbing and leaves the room.\n");
    }
    await UNPRIORITIZE(MRS_ROBNER);
    move(MRS_ROBNER, CORRIDOR_1);
    flg = true;
  } else if (loc(GEORGE) == DUNBAR_ROOM) {
    if (g.HERE == DUNBAR_ROOM) {
      tell("George says something like \"My God\" under his breath.\n");
    }
    await UNPRIORITIZE(GEORGE);
  } else if (loc(ROURKE) == CORRIDOR_1) {
    if (g.HERE == CORRIDOR_1) {
      tell("Mrs. Rourke peeks in the door and looks sick. \"I'm leaving this house,\" she says, and pops out again.\n");
    }
    move(ROURKE, STAIR_TOP);
    await ESTABLISH_GOAL(ROURKE, ROURKE_ROOM, true);
    flg = true;
  }
  if ((g.SHOT_COUNT = g.SHOT_COUNT + 1) > 20) {
    await QUEUE(I_SHOT.id, 0);
  }
  return flg;
}

