async function GLOBAL_ROOM_F() {
  let tim = 0;
  if (isVerb(V.THROUGH)) {
    return await V_WALK_AROUND();
  } else if (isVerb(V.KNOCK)) {
    if (g.HERE == UPSTAIRS_CLOSET) {
      tell("The wall to the north here sounds unusually hollow.\n");
      return true;
    } else if (eq(getProp(g.HERE, P.LINE), OUTSIDE_LINE_C)) {
      tell("You're acting very strangely!\n");
      return true;
    } else {
      tell("Knocking on the walls reveals nothing unusual.\n");
      return true;
    }
  } else if (isVerb(V.LOOK_INSIDE) && (g.HERE == CORRIDOR_2)) {
    tell("From here, it looks quite ordinary.\n");
    return true;
  } else if (isVerb(V.SEARCH, V.EXAMINE)) {
    if (eq(getProp(g.HERE, P.LINE), OUTSIDE_LINE_C)) {
      tim = 10;
    } else if (!(getProp(g.HERE, P.CORRIDOR) == 0)) {
      tim = 3;
    } else {
      tim = 2 + getProp(g.HERE, P.SIZE);
    }
    tell("An exhaustive search of even a single room would take hours. A more productive approach would be to examine or search various items of interest within the room. A cursory search would take on the order of ", N(tim), " minutes, but it wouldn't reveal much. Would you like to do it anyway? (Y/N)");
    if (await YES$()) {
      if (await INT_WAIT(tim)) {
        tell("Your brief search revealed nothing that was not obvious before.\n");
        return true;
      } else {
        tell("You didn't get a chance to finish looking over the room.\n");
        return true;
      }
    } else {
      tell("Ok.\n");
      return true;
    }
  } else {
    return false;
  }
}

