async function OBJECT_PAIR_F() {
  if (isVerb(V.ARREST)) {
    if (g.PRESENT_TIME < 600) {
      tell("It is rather early in the case to be making hasty judgments.\n");
      return true;
    } else if ((eq(get(g.P_PRSO, 1), BAXTER, GLOBAL_BAXTER) && eq(get(g.P_PRSO, 2), DUNBAR, GLOBAL_DUNBAR)) || (eq(get(g.P_PRSO, 1), DUNBAR, GLOBAL_DUNBAR) && eq(get(g.P_PRSO, 2), BAXTER, GLOBAL_BAXTER))) {
      if (g.CORPSE_SEEN) {
        tell("Ms. Dunbar is dead!\n");
      } else if (g.DUNBAR_DEAD) {
        tell("Sergeant Duffy rushes into view. \"Ms. Dunbar is dead! She has shot herself in her room! Come quickly!\" He dashes off.\n");
      } else if (hasFlag(BAXTER_PAPERS, TOUCHBIT) && hasFlag(LAB_REPORT, TOUCHBIT) && g.NOTE_READ && g.STUB_D) {
        crlf();
        (await END_HEADER("September 5"));
        tell("Congratulations on your superb handling of the Robner case. As you have probably heard, a jury convicted Mr. Baxter and Ms. Dunbar today of the murder of Mr. Robner. Thanks to you, the murderers will be behind bars, possibly for the rest of their lives. Thanks for a job brilliantly done. Which reminds me of another fascinating case I would like to assign you to...\n\nComing soon: Another INTERLOGIC Mystery from Infocom\n\n");
        await EPILOGUE();
      } else if (g.PRESENT_TIME < 700) {
        tell("You realize the arrest would be a trifle premature, since you're not even sure that a murder was committed.\n");
      } else if (!(hasFlag(LAB_REPORT, TOUCHBIT))) {
        crlf();
        (await END_HEADER("August 19"));
        tell("The District Attorney has decided not to seek an indictment in the Robner case. He points out that it has never been proven that a murder was committed, despite the deep suspicions to the contrary. Thanks for your help on this case. It's too bad we couldn't find out more about the circumstances surrounding the death of Mr. Robner.\n\n");
      } else if (!(hasFlag(BAXTER_PAPERS, TOUCHBIT))) {
        crlf();
        (await END_HEADER("September 2"));
        tell("A grand jury looking into the death of Mr. Robner has decided not to indict the accused. They felt that the lack of motive as well as the contorted hypothesis involving the actual mechanism of the murder of Mr. Robner was not convincing. Personally, I think you're on the right track, but I must admit that the evidence is meager. Thank you for helping in the case.\n\n");
      } else if (!g.NOTE_READ) {
        crlf();
        (await END_HEADER("October 4"));
        tell("The jury in the Robner case has declined to convict Mr. Baxter and Ms. Dunbar. Appearances indicate that the verdict was difficult, and that several jury members were convinced that the two were guilty. However, no evidence was presented directly relating the Focus case with the murder of Mr. Robner. This left the question of motive unresolved. I appreciate your efforts in the case and am sorry to report this outcome to you.\n\n");
      } else {
        crlf();
        (await END_HEADER("October 6"));
        tell("The jury in the Robner case has declined to convict Mr. Baxter and Ms. Dunbar. Although most of the jury was convinced of their guilt, it seems that one or two felt there was some reasonable doubt about the proposed conspiracy. Their main concern was the lack of evidence that Baxter was near the grounds on the night of the murder. His alibi of having been to the symphony was confirmed by several people. Although this doesn't mean that he didn't go back to the Robner estate later, it nevertheless was not convincing. Thank you for your excellent efforts. It is sad to think that we may have let the murderers slip between our fingers.\n\n");
      }
      return await CASE_OVER();
    } else if ((eq(get(g.P_PRSO, 1), BAXTER, GLOBAL_BAXTER) && eq(get(g.P_PRSO, 2), GEORGE, GLOBAL_GEORGE)) || (eq(get(g.P_PRSO, 1), GEORGE, GLOBAL_GEORGE) && eq(get(g.P_PRSO, 2), BAXTER, GLOBAL_BAXTER))) {
      if (!(hasFlag(LAB_REPORT, TOUCHBIT))) {
        tell("You realize that there is no evidence that a murder has been committed and decide not to go ahead with the arrest.\n");
        return true;
      } else if ((g.NEW_WILL_SEEN || g.GEORGE_RUN) && hasFlag(BAXTER_PAPERS, TOUCHBIT) && g.NOTE_READ) {
        crlf();
        (await END_HEADER("November 12"));
        tell(" The district attorney, after extensive interrogation of George Robner and Mr. Baxter, has declined to seek an indictment against them. He agrees that there has been foul play in the death of Mr. Robner and that both suspects have motives for the crime. However, no coherent theory could be proposed which involved the two of them conspiring to murder Mr. Robner. On the other hand, it seems unlikely that either of them alone could have committed the crime. I am sorry that your work has gone for naught.\n\n");
        return await CASE_OVER();
      } else {
        crlf();
        (await END_HEADER("August 1"));
        tell("The district attorney has declined to indict George Robner and Mr. Baxter in the death of Marshall Robner, noting that there is no link between the accused, except hatred, and that all of the evidence is circumstantial. I wish you luck on your future cases.\n\n");
        return await CASE_OVER();
      }
    } else {
      tell("You realize that this arrest is quite farfetched and would result only in your humiliation.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function EPILOGUE() {
  crlf();
  tell("You have solved the case! If you would like, you may see the author's summary of the story. We would advise you to come up with your own first! Would you like to see the author's summary? (Y/N)");
  if (await YES$()) {
    crlf();
    tell("Mr. Robner's work was his life, as pointed out by a number of the principals. George knew that his father had lost control of the company, and a story in the newspaper indicated that Baxter intended to sell the company to a multi-national conglomerate, presumably to advance his career. Baxter admitted to the merger plans, but indicated that Mr. Robner was in complete agreement. This is contrary to what George and Mrs. Robner said. The note pad found in the library was Robner's last, desperate attempt to save the company, in which Robner threatened to expose Baxter's involvement in the Focus scandal. Baxter denied getting the note, but it was not in the trash. The papers detailing Baxter's criminality in the scandal were kept locked in a safe in a hidden closet near the library. Only George and Marshall Robner knew the whereabouts of the safe.\n  Baxter planned to murder his partner, aided by the fact that Robner was known to be depressed, even suicidal. He enlisted the help of his lover, Dunbar, one of whose medicines was found to interact fatally with the pills Robner was taking. The relationship of Baxter and Dunbar was kept quiet, although Mrs. Rourke had an inkling of it. After the concert in Hartford which both Baxter and Dunbar attended, they returned to the Robner estate. Dunbar placed some LoBlo in Robner's tea. After Robner died, Baxter used the ladder from the shed to enter the library and exchange the incriminating cup for a clean one (counting the china in the kitchen reveals that a cup is missing). Coming down the ladder, Baxter presumably dropped the cup and inadvertently left one piece on the ground in the rose garden, near the ladder holes that McNabb found while tending his roses.\n\n");
  }
  return await quit();
}

async function COM_CHECK(person) {
  if (isVerb(V.WHAT)) {
    g.WINNER = PLAYER;
    await PERFORM(V.ASK_ABOUT, person, g.PRSO);
    return true;
  } else if (isVerb(V.EXAMINE)) {
    g.WINNER = PLAYER;
    await PERFORM(V.SHOW, person, g.PRSO);
    return true;
  } else if (isVerb(V.TELL_ME) && (g.PRSO == PLAYER)) {
    g.WINNER = PLAYER;
    await PERFORM(V.ASK_ABOUT, person, g.PRSI);
    return true;
  } else if (isVerb(V.SHOW) && (g.PRSO == PLAYER)) {
    tell("\"I'm sure you can find it, Inspector.\"\n");
    return true;
  } else if (isVerb(V.FOLLOW) && (g.PRSO == PLAYER)) {
    tell("\"I would rather not.\"\n");
    return true;
  } else {
    return false;
  }
}

