async function UNPRIORITIZE(person) {
  let gt = 0;
  gt = get(g.GOAL_TABLES, getProp(person, P.CHARACTER));
  put(gt, GOAL_PRIORITY, false);
  if (get(gt, GOAL_QUEUED)) {
    await ESTABLISH_GOAL(person, get(gt, GOAL_QUEUED));
    return put(gt, GOAL_QUEUED, false);
  } else {
    return false;
  }
}

async function ESTABLISH_GOAL(person, goal, priority = false) {
  let here = loc(person), hl = 0, gl = 0, gt = 0;
  gt = get(g.GOAL_TABLES, getProp(person, P.CHARACTER));
  if (priority) {
    put(gt, GOAL_ENABLE, true);
    put(gt, GOAL_PRIORITY, true);
    put(gt, GOAL_QUEUED, here);
  }
  if (eq(hl = getProp(here, P.LINE), gl = getProp(goal, P.LINE))) {
    put(gt, GOAL_I, false);
  } else if (hl == TOP_OF_THE_LINE_C) {
    put(gt, GOAL_I, STAIR_TOP);
  } else if (hl == OUTSIDE_LINE_C) {
    put(gt, GOAL_I, FRONT_PATH);
  } else if (hl == FOOD_LINE_C) {
    put(gt, GOAL_I, CORNER);
  } else if (gl == TOP_OF_THE_LINE_C) {
    put(gt, GOAL_I, STAIR_BOTTOM);
  } else if (gl == FOOD_LINE_C) {
    put(gt, GOAL_I, NFOYER);
  } else {
    put(gt, GOAL_I, FOYER);
  }
  put(gt, GOAL_S, getProp(goal, P.STATION));
  put(gt, GOAL_F, goal);
  return loc(person);
}

async function FOLLOW_GOAL(person) {
  let here = loc(person), line = 0, ln = 0, rm = 0, gt = 0, goal = 0, flg = 0, goal_flag = false, igoal = false, loc_ = 0, cnt = 1, dir = 0;
  gt = get(g.GOAL_TABLES, getProp(person, P.CHARACTER));
  if (here == get(gt, GOAL_F)) {
    flg = await GOAL_REACHED(person);
    put(gt, GOAL_S, false);
    return flg;
  } else if (!(get(gt, GOAL_ENABLE))) {
    return false;
  }
  if (!(eq(loc_ = getProp(here, P.STATION), here))) {
    return await MOVE_PERSON(person, loc_);
  }
  if (goal = get(gt, GOAL_I)) {
    igoal = true;
  } else {
    goal = get(gt, GOAL_S);
  }
  if (!goal) {
    return false;
  } else if (here == STAIRS) {
    return await TRANSFER(person, here, get(gt, GOAL_F));
  } else if (here == goal) {
    if (igoal) {
      return await TRANSFER(person, goal, get(gt, GOAL_F));
    } else if (!(here == get(gt, GOAL_F))) {
      flg = await MOVE_PERSON(person, get(gt, GOAL_F));
      put(gt, GOAL_S, false);
      if (flg) {
        await GOAL_REACHED(person);
      } else {
        flg = await GOAL_REACHED(person);
      }
      return flg;
    } else {
      put(gt, GOAL_S, false);
      return await GOAL_REACHED(person);
    }
  }
  ln = getProp(goal, P.LINE);
  line = ln == TOP_OF_THE_LINE_C ? g.TOP_OF_THE_LINE : (ln == BOTTOM_LINE_C ? g.BOTTOM_LINE : (ln == FOOD_LINE_C ? g.FOOD_LINE : g.OUTSIDE_LINE));
  for (;;) {
    if (eq(rm = get(line, cnt), here)) {
      if (goal_flag) {
        loc_ = get(line, cnt - 3);
      } else {
        loc_ = get(line, cnt + 3);
      }
      return await MOVE_PERSON(person, loc_);
    } else if (rm == goal) {
      goal_flag = true;
    }
    cnt = cnt + 3;
  }
}

async function GOAL_REACHED(person) {
  return await apply(get(get(g.GOAL_TABLES, getProp(person, P.CHARACTER)), GOAL_FUNCTION), G_REACHED);
}

async function MOVE_PERSON(person, where) {
  let dir = 0, gt = 0, ol = 0, cor = 0, pcor = 0, chr = 0, nc = 0, wt = 0, cnt = 0, flg = false, ex = 0;
  gt = get(g.GOAL_TABLES, chr = getProp(person, P.CHARACTER));
  nc = chr;
  ol = loc(person);
  dir = await DIR_FROM(ol, where);
  if (eq(propSize(ex = getPropAddr(ol, dir)), DEXIT)) {
    if (!(hasFlag(ex = getb(ex, DEXITOBJ), OPENBIT))) {
      setFlag(ex, OPENBIT);
    } else {
      ex = false;
    }
  } else {
    ex = false;
  }
  put(gt, GOAL_LDIR, dir);
  if (ol == g.HERE) {
    flg = true;
    tell(D(person));
    if (dir == P.OUT) {
      tell(" walks out of the room.\n");
    } else if (dir == P.DOWN) {
      tell(" is going downstairs.\n");
    } else if (dir == P.UP) {
      tell(" is going upstairs.\n");
    } else if (dir == P.IN) {
      if (ex) {
        tell(" opens the ", D(ex), " and");
      }
      tell(" goes into another room.");
    } else {
      if (ex) {
        tell(" opens the ", D(ex), " and");
      }
      tell(" heads off to ");
      await DIR_PRINT(dir);
      tell(".\n");
    }
  } else if (where == g.HERE) {
    flg = true;
    tell(D(person));
    if (!(g.HERE == get(gt, GOAL_F))) {
      tell(" is walking past you.\n");
    } else if (eq(getProp(g.HERE, P.LINE), OUTSIDE_LINE_C)) {
      tell(" stops here.\n");
    } else {
      tell(" steps into the room.\n");
    }
  } else if (cor = getProp(g.HERE, P.CORRIDOR)) {
    if ((pcor = getProp(ol, P.CORRIDOR)) && !(eq(cor & pcor, 0))) {
      flg = true;
      if (where == STAIRS) {
        tell(D(person), " steps onto the stairs.\n");
      } else if (!(getProp(where, P.CORRIDOR))) {
        tell(D(person), ", off to ");
        await DIR_PRINT(await COR_DIR(g.HERE, ol));
        tell(",");
        if (ex) {
          tell(" opens a door and");
        }
        if (eq(getProp(g.HERE, P.LINE), OUTSIDE_LINE_C)) {
          tell(" leaves your view");
        } else if (where == SHED_ROOM) {
          tell(" darts into the shed");
        } else {
          tell(" ducks into a room");
        }
        tell(" to ");
        await DIR_PRINT(await DIR_FROM(ol, where));
        tell(".\n");
      } else if ((cor & getProp(where, P.CORRIDOR)) == 0) {
        tell(D(person), ", off to ");
        await DIR_PRINT(await COR_DIR(g.HERE, ol));
        tell(", disappears from sight ");
        pcor = await DIR_FROM(ol, where);
        if (pcor == P.UP) {
          tell("up the stairs");
        } else if (pcor == P.DOWN) {
          tell("down the stairs");
        } else {
          tell("to ");
          await DIR_PRINT(pcor);
        }
        tell(".\n");
      } else {
        tell(D(person), " is to ");
        await DIR_PRINT(await COR_DIR(g.HERE, where));
        tell(", heading toward ");
        await DIR_PRINT(await DIR_FROM(ol, where));
        tell(".\n");
      }
    } else if ((pcor = getProp(where, P.CORRIDOR)) && !(eq(cor & pcor, 0))) {
      flg = true;
      tell("To ");
      await DIR_PRINT(await COR_DIR(g.HERE, where));
      tell(" ", D(person));
      if (eq(getProp(where, P.LINE), OUTSIDE_LINE_C) || (where == STAIRS)) {
        tell(" comes into view from ");
      } else {
        tell(" enters the hallway from ");
      }
      await DIR_PRINT(await DIR_FROM(where, ol));
      tell(".\n");
    }
  }
  wt = get(g.WHERE_TABLES, chr);
  loop1: for (;;) {
    if (cnt > CHARACTER_MAX) {
      break loop1;
    } else {
      if (eq(chr = get(g.CHARACTER_TABLE, cnt), person)) {
      } else if (((cnt == 0) && flg) || (loc(get(g.CHARACTER_TABLE, cnt)) == ol)) {
        put(wt, cnt, g.PRESENT_TIME);
        put(get(g.WHERE_TABLES, cnt), nc, g.PRESENT_TIME);
      }
      cnt = cnt + 1;
    }
  }
  move(person, where);
  return flg;
}

async function DIR_FROM(here, there) {
  let p_ = 0, l = 0, tx = 0, o = 0;
  p_ = 0;
  for (;;) {
    if ((p_ = nextProp(here, p_)) == 0) {
      return false;
    } else if (p_ == P.IN || p_ == P.OUT) {
    } else if (!(p_ < LOW_DIRECTION)) {
      tx = getPropAddr(here, p_);
      l = propSize(tx);
      if ((l == DEXIT || l == UEXIT || l == CEXIT) && eq(getb(tx, REXIT), there)) {
        return p_;
      }
    }
  }
}

async function COR_DIR(here, there) {
  let cor = 0, rm = 0, past = 0, cnt = 2;
  cor = await GET_COR(getProp(there, P.CORRIDOR) & getProp(here, P.CORRIDOR));
  loop1: for (;;) {
    if (eq(rm = get(cor, cnt), here)) {
      past = 1;
      break loop1;
    } else if (rm == there) {
      break loop1;
    }
    cnt = cnt + 1;
  }
  return get(cor, past);
}

async function GET_COR(num) {
  if (num == 1) {
    return g.COR_1;
  } else if (num == 2) {
    return g.COR_2;
  } else if (num == 4) {
    return g.COR_4;
  } else if (num == 8) {
    return g.COR_8;
  } else if (num == 16) {
    return g.COR_16;
  } else if (num == 32) {
    return g.COR_32;
  } else if (num == 64) {
    return g.COR_64;
  } else if (num == 128) {
    return g.COR_128;
  } else if (num == 256) {
    return g.COR_256;
  } else if (num == 512) {
    return g.COR_512;
  } else if (num == 1024) {
    return g.COR_1024;
  } else {
    return g.COR_2048;
  }
}

async function TRANSFER(person, igoal, fgoal) {
  let v_ = 0, flg = false;
  if (igoal == STAIR_TOP) {
    if ((g.HERE == STAIR_BOTTOM || g.HERE == NFOYER || g.HERE == ROURKE_ROOM) || (g.HERE == LIVING_ROOM || g.HERE == FOYER || g.HERE == CORNER)) {
      tell("You can hear footsteps on the staircase.\n");
      flg = true;
    }
    return (await MOVE_PERSON(person, STAIRS)) || flg;
  } else if (igoal == STAIR_BOTTOM) {
    if ((g.HERE == STAIR_TOP || g.HERE == CORRIDOR_1) || (g.HERE == CORRIDOR_2 || g.HERE == CORRIDOR_3)) {
      tell("You can hear footsteps on the staircase.\n");
      flg = true;
    }
    return (await MOVE_PERSON(person, STAIRS)) || flg;
  } else {
    v_ = igoal == STAIRS ? (eq(getProp(fgoal, P.LINE), 0) ? (await MOVE_PERSON(person, STAIR_TOP)) : (await MOVE_PERSON(person, STAIR_BOTTOM))) : (igoal == FRONT_PATH ? (setFlag(FRONT_DOOR, OPENBIT), await MOVE_PERSON(person, FOYER)) : (igoal == FOYER ? (setFlag(FRONT_DOOR, OPENBIT), await MOVE_PERSON(person, FRONT_PATH)) : (igoal == NFOYER ? (await MOVE_PERSON(person, CORNER)) : (await MOVE_PERSON(person, NFOYER)))));
    await ESTABLISH_GOAL(person, fgoal);
    return v_;
  }
}

async function DIR_PRINT(dir) {
  let cnt = 0;
  for (;;) {
    if (eq(get(g.DIR_STRINGS, cnt), dir)) {
      if (!(dir == P.UP || dir == P.DOWN)) {
        tell("the ");
      }
      printS(get(g.DIR_STRINGS, cnt + 1));
      return true;
    }
    cnt = cnt + 1;
  }
}

